//! Central configuration registry — every Selphi env-var knob in one place.
//!
//! Backward-compatible config file: `--config selphi.toml` sets process env vars
//! (ONLY when not already set, so an explicit env var still overrides the file), and
//! the existing `std::env::var` reads throughout the code are unchanged. `--dump-config`
//! writes the full effective configuration as documented TOML. Precedence:
//! built-in default  <  --config file  <  environment variable  <  CLI flag.
//!
//! TOML keys are the literal env-var names; a bool knob set `true` exports it as "1"
//! (its presence is what the code tests), `false`/absent leaves it unset. This file is
//! GENERATED from a code inventory (workflow worer0ps7); regenerate if knobs change.

use std::fmt::Write as _;

#[derive(Clone, Copy, PartialEq, Eq)]
enum Kind { Bool, Value }

struct Knob {
    name: &'static str,
    group: &'static str,
    kind: Kind,
    default_repr: &'static str,
    user_facing: bool,
    doc: &'static str,
}

/// All env-var knobs, grouped. Sorted user-facing-first within each group.
static KNOBS: &[Knob] = &[
    Knob { name: "SELPHI_AUTOROUTE_WGS_DENSITY", group: "autoroute", kind: Kind::Value, default_repr: "1000", user_facing: true, doc: "Min site density (variants/Mb) at which a confident GT callset with a GQ/DP field routes to refine (below = chip array → plain genotype). parse::<f64>(), filter(f>=0.0), unwrap_or(1000.0)." },
    Knob { name: "SELPHI_AUTOROUTE_MAXBYTES", group: "autoroute", kind: Kind::Value, default_repr: "268435456", user_facing: false, doc: "Cap (bytes) on how much of a VCF-text target the engine-sniff decompresses into memory. parse::<u64>() (registry uses usize to avoid >4GiB truncation), filter(n>0), unwrap_or(256<<20=256 MiB). BCF ..." },
    Knob { name: "SELPHI_AUTOROUTE_SAMPLE", group: "autoroute", kind: Kind::Value, default_repr: "2000", user_facing: false, doc: "Number of data records the engine-sniffer samples to decide the route. parse::<usize>(), filter(n>0), unwrap_or(2000)." },
    Knob { name: "SELPHI_PHASE_STREAM_MIN_SAMPLES", group: "phasing", kind: Kind::Value, default_repr: "16000", user_facing: false, doc: "--phase-panel: minimum sample count at which an indexed-BCF cohort uses the STREAMING phasing path (chunk-by-chunk range reads + incremental write, bounded memory) instead of the in-RAM path that holds the full n_var×n_haps input+output arrays. Below this → in-RAM (byte-identical). usize_or, default 16000. Set to 1 to force streaming (byte-identity testing)." },
    Knob { name: "LCWGS_CHUNK_BUFFER_CM", group: "lcwgs", kind: Kind::Value, default_repr: "0.5", user_facing: true, doc: "cM buffer added each side of the core; HMM runs over core+2×buffer but only core dosage kept (absorbs FB edge effects). .parse().unwrap_or(0.5)." },
    Knob { name: "LCWGS_CHUNK_CORE_CM", group: "lcwgs", kind: Kind::Value, default_repr: "16.0", user_facing: true, doc: "cM span of each chunk's core region (HMM window) whose dosage is kept. DEFAULT 16.0 — real-GIAB sweep sweet spot for overall R² (mean 0.9201 vs 0.9184 at 2.0, vs GLIMPSE2 0.9155); ~1.5× the 2-cM wall, still ~2.7× faster than GLIMPSE2 single-sample. Set 2.0 for the prior faster/lower default. .parse().unwrap_or(16.0)." },
    Knob { name: "LCWGS_CHUNK_MAX_PANEL_GB", group: "lcwgs", kind: Kind::Value, default_repr: "", user_facing: false, doc: "Cap on the panel rows one lcWGS chunk holds, in GB of its two bit copies (2 x sites x ceil(n_ref/64) x 8 bytes; 2 GB = ~105,800 sites on 75,552 haplotypes, ~1.26 M on 6,332). A cM chunk whose buffer holds more sites is cut into equal-count sub-cores of <= 3/4 of the cap, each buffered by the cM buffer clipped to cap/8 sites a side, so pericentromeric chunks cannot set the peak. Unset (default) or <= 0 = no cap (cM chunks exactly, byte-identical); chunks within the cap are unchanged when set. Active (non-passenger) sites only. f64_opt." },
    Knob { name: "LCWGS_CHRWIDE_PBWT", group: "lcwgs", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Select the conditioning set ONCE over the whole chromosome's common-site scaffold (long-range IBD, genotype-engine-style) and reuse it for every cM chunk, instead of per-chunk local selection. present(); default OFF → byte-identical per-chunk path. Improves the rare bin under sticky (K-indep) copy." },
    Knob { name: "LCWGS_INDEL_REALIGN", group: "lcwgs", kind: Kind::Bool, default_repr: "false", user_facing: true, doc: "Read-vs-haplotype pair-HMM indel likelihoods (needs --reference). With LCWGS_BAM_INDELS unset or =keep the --bam path puts the indels IN the chain with these likelihoods (measured: -2.17 pp SNP non-ref concordance on six capture libraries, 0/6: miscalibrated at low depth); with LCWGS_BAM_INDELS=impute (the default when this knob is unset) each impute-only indel folds its own reads into its genotype once (SNPs unchanged; indel het precision -6.5 pp: not recommended). present(); default OFF." },
    Knob { name: "LCWGS_KMAX", group: "lcwgs", kind: Kind::Value, default_repr: "3000", user_facing: true, doc: "Conditioning-set size ceiling after augmentation; LCWGS_KMAX=0 disables the cap (unlimited). match envu: Some(0)=>None(uncapped), Some(k)=>Some(k), None=>Some(3000). 0 is the special uncap value." },
    Knob { name: "LCWGS_KMAX_CUT", group: "lcwgs", kind: Kind::Value, default_repr: "", user_facing: false, doc: "How the rare-carrier augmentation cuts a conditioning set at LCWGS_KMAX (src/lcwgs/kmax_cut.rs). The set is the sample's selection base (PBWT union capped at LCWGS_KPBWT) followed by the carriers of the rare sites the haplotype is sampled to carry; the cut keeps the first LCWGS_KMAX distinct IDs. Unset/empty/`prefix`/`0`/`off`/`false`/`no`/`n` = that prefix cut (default, byte-identical): with a base deeper than LCWGS_KMAX (the adaptive 4,986 > 3000 on the 75,552-hap v3 panel) no carrier enters the main pass, and a `g2` base, emitted index-sorted, is cut to its LOWEST indices (on v3 the UK Biobank block). `priority` = the selector emits the base in its priority order (`g2`: its fill order, best rank first; hash/hybrid: theirs), the base is cut in that order and the kept part is sorted ascending (packing speed; both haplotypes of a sample keep the same head). Acts only where a base can exceed the room left (LCWGS_KPBWT, or the longest supplied list, > LCWGS_KMAX - min(LCWGS_CARRIER_RESERVE, LCWGS_KMAX)): with the default depth 2000 and k_max 3000 (panels below 30,311 haplotypes) never alone, nor with a reserve <= 1000; each pass applies the rule at its own depth and k_max: on a biobank-size panel the default SPLIT deep pass runs at depth 2000 / k_max 3000 (LCWGS_BIG_PANEL), so there priority alone has no effect and a reserve has one only above 1000 (with LCWGS_BIG_PANEL=order: depth 4,986 / LCWGS_SPLIT_KMAX 5000, a reserve above 14). The iteration-0 INIT set (and LCWGS_CHRWIDE_PBWT conditioning, which is that set) has no rank order: it is ascending, so its cut keeps the lowest indices as before. Measured on v3 (chr22, six GIAB capture libraries, seed 0, on top of LCWGS_BIG_PANEL=order), priority with LCWGS_CARRIER_RESERVE=1000: the main pass then admits ~420 carriers per haplotype and the 0.5-5% bin reaches GLIMPSE2's (+0.104 pp), non-reference +0.174 vs GLIMPSE2 (rank order alone: +0.233), but the European samples lose MAF >= 10% (HG003 10-20% -0.215 vs the index order; priority without a reserve -0.330): not the default (the biobank-size SPLIT, LCWGS_BIG_PANEL, keeps the main pass for >= 10%). Another value is said and treated as unset. raw()." },
    Knob { name: "LCWGS_CARRIER_RESERVE", group: "lcwgs", kind: Kind::Value, default_repr: "0", user_facing: false, doc: "Rare-carrier slots held in the LCWGS_KMAX cut (src/lcwgs/kmax_cut.rs): per sample r = min(N, LCWGS_KMAX, the larger of its two haplotypes' distinct carrier counts); both haplotypes keep the first LCWGS_KMAX - r base IDs (in the base's order, or by LCWGS_KMAX_CUT=priority), then their carriers, then the rest of the base until LCWGS_KMAX, so the set size is unchanged and unused reserved slots return to the base. 0 (default) = the old cut. Acts only where LCWGS_KPBWT (or the longest supplied conditioning list) > LCWGS_KMAX - min(N, LCWGS_KMAX) (so on panels below 30,311 haplotypes only for N > 1000 at the defaults), in the main pass and, at its own depth and k_max, the SPLIT deep pass (on a biobank-size panel by default depth 2000 / k_max 3000: only for N > 1000). Measured on v3 (chr22, six GIAB capture libraries, seed 0, on top of LCWGS_BIG_PANEL=order): N=1000 alone non-reference +0.191 vs GLIMPSE2 (rank order alone +0.233), 0.5-5% +0.046, European MAF >= 10% lower (HG003 10-20% -0.215 vs the index order): not the default. usize_opt, default 0." },
    Knob { name: "LCWGS_KPBWT", group: "lcwgs", kind: Kind::Value, default_repr: "2000", user_facing: true, doc: "Max reference haplotypes per sample in the conditioning set (the PBWT layer union is capped at it). envu, default 2000. PRESENCE-GATED: when UNSET the depth is adaptive, round(0.066 x n_ref) clamped to [2000, 5000] (= 2000 on panels of 2,001-30,310 haplotypes; 4,986 on the 75,552-hap v3 panel, where above 3000 it also switches the auto SPLIT deep pass on at soft coverage). Setting it pins the depth on every panel. On a biobank-size panel the cap order is GLIMPSE2's (LCWGS_BIG_PANEL) whatever the depth; LCWGS_KPBWT=2000 there runs one pass (no SPLIT: depth <= 3000), the computation the default's SPLIT deep pass uses for MAF 0.5-10%: about half the default's CPU and above GLIMPSE2 on v3, but it lowers two European samples' common SNPs below the index order (see LCWGS_BIG_PANEL)." },
    Knob { name: "LCWGS_BIG_PANEL", group: "lcwgs", kind: Kind::Value, default_repr: "", user_facing: true, doc: "lcWGS conditioning on a biobank-size panel (>= 30,311 haplotypes: the first size at which the adaptive depth round(0.066 x n_ref) exceeds 2000; taken from that rule, not measured: nothing between 6,332 and 75,552 haplotypes has been measured). Unset (default) = ON for such panels, said loudly in the log, two parts. (1) ORDER: the per-sample PBWT union is capped in GLIMPSE2 rank order (as LCWGS_QUAL_TRUNC=g2) instead of by haplotype index, at the same depth (LCWGS_KPBWT, else adaptive: 4,986 on the 75,552-hap v3 panel). The index order keeps whatever block the panel lists first: on v3 (34,582 UK Biobank samples first) every sample conditions on UK Biobank haplotypes only. (2) SPLIT: when the auto SPLIT engages (depth > 3000 and soft likelihoods, LCWGS_NO_SPLIT), its deep pass runs at depth 2000 / k_max 3000 (= the computation of a whole LCWGS_KPBWT=2000 run: 2,000 rank-ordered haplotypes plus up to 1,000 rare carriers) and owns panel MAF 0.5-10% instead of 5-10%; sites >= 10% and < 0.5% keep the main pass (whose 3000-slot cut of the deeper base, 4,986 on v3, keeps no rare carrier). LCWGS_SPLIT_BAND / LCWGS_SPLIT_KMAX / LCWGS_SPLIT_KPBWT each override their part; LCWGS_SPLIT_MAF keeps its own defaults (k_max 5000, the run's depth); not with LCWGS_CHRWIDE_PBWT (old split). An explicit LCWGS_QUAL_TRUNC (or a cap plan supplied by a library caller) wins for the order only. `order` = the rank order with the old SPLIT (5-10%, k_max 5000, the run's depth). `0`/`off`/`false`/`no`/`n` = the index order and the old SPLIT on every panel: the master conditioning, byte-identical to it (the master --bam output also needs LCWGS_BAM_INDELS=drop). Panels below the boundary are unaffected either way. Measured on v3, chr22, six GIAB capture libraries (HG002-HG007), allele-keyed non-reference concordance, wins over non-tied pairs. vs the index order (12 sample-seed pairs: seeds 0-2 on HG002-4, seed 0 on HG005-7): 97.807 -> 98.658 (+0.851 pp [+0.057,+1.646], 12/12; MAF >= 5% +0.413 11/12, 0.5-5% +1.993 12/12, < 0.5% +10.876 12/12); no sample below the index order in any fine MAF bin beyond seed noise (CIs span 0 in 4 of 7 bins); European heterozygote precision +0.016/-0.014/+0.010. vs GLIMPSE2 (production commit, same panel; 18 pairs, seeds 0-2 on all six): 98.358 -> 98.676 (+0.318 [+0.209,+0.428] 18/18; het precision +0.303 18/18; >= 5% +0.349 18/18; 0.5-5% +0.136 [-0.245,+0.517] 12/17; < 0.5% -0.071 [-2.277,+2.136] 12/17); indels +0.543 [+0.372,+0.715] 18/18. vs `order` (18 pairs): +0.061 [+0.015,+0.107] 18/18, 0.5-5% +0.889 [+0.134,+1.644] 17/17, >= 5% +0.003, < 0.5% and >= 10% identical by construction, het precision -0.011 [-0.028,+0.006] 5/18; indels -0.028 [-0.100,+0.045] 6/16 (0.5-5% -0.579 [-1.441,+0.283] 3/15). The 0.5% and 10% edges were chosen on these six samples. PL route (HG002 4x and 30x PL files listing the 1KG panel's sites, 1.58 M v3 SNPs padded flat, 3 seeds) vs the index order: non-ref +0.118 / +0.124 3/3, not below it beyond noise in any of the three MAF bins by the 3-seed mean (one genome) (>= 5% +0.055 / +0.022, 0.5-5% +0.582 / +1.018, < 0.5% +1.443 / +1.898), heterozygote precision -0.178 / -0.139 (0/3; `order`: -0.118 / -0.064). Cost chr22 NA24143, 4 threads, each run alone: index order 1,025 s / 2,591 CPU-s / 8.14 GiB (no indels), `order` 1,229 / 3,031 / 9.55, this default 1,135 / 2,796 / 9.08. LCWGS_KPBWT=2000 (single pass, no SPLIT: 596 s / 1,480 CPU-s) stays the cheapest configuration above GLIMPSE2 (+0.160 [+0.055,+0.264], 17 wins / 1 tie) but lowers European HG003/HG004 common SNPs by 0.205/0.089 pp vs the index order. raw()." },
    Knob { name: "LCWGS_MEM_BUDGET_GB", group: "lcwgs", kind: Kind::Value, default_repr: "input-sized process allowance", user_facing: true, doc: "lcWGS memory target in decimal GB. One sample uses byte admission with 65% of the reconstructed working envelope. Multiple samples use Rayon chunk waves with an RSS reclamation target of shared storage plus 80% of that envelope; freed worker pages are collected above 75% of the target. Default wave admission uses half host RAM and accounts for active sample slots. An explicit target also constrains the wave estimate after shared storage. Neither estimate nor reclamation is an OS RSS limit. Scheduling preserves output bits. f64_opt." },
    Knob { name: "LCWGS_NE", group: "lcwgs", kind: Kind::Value, default_repr: "100000", user_facing: true, doc: "Effective population size for Li-Stephens recombination in the lcWGS HMM. envf.unwrap_or(100000.0)." },
    Knob { name: "LCWGS_N_ITER", group: "lcwgs", kind: Kind::Value, default_repr: "30", user_facing: true, doc: "Total Gibbs iterations alternating imputation and phasing; the last LCWGS_N_MAIN (25) are averaged, the rest are burn-in. Default 30 (5 burn-in): as accurate as 50 on real-depth data at 39% less wall time. envu.unwrap_or(30)." },
    Knob { name: "LCWGS_N_MAIN", group: "lcwgs", kind: Kind::Value, default_repr: "25", user_facing: true, doc: "Number of main (post burn-in) iterations whose posterior dosages are averaged for output. envu.unwrap_or(25)." },
    Knob { name: "LCWGS_GIBBS_RESTARTS", group: "lcwgs", kind: Kind::Value, default_repr: "1", user_facing: true, doc: "Multi-restart Gibbs averaging: number of independent Gibbs chains (seeds seed, seed+1, …) whose per-(variant×sample) dosages/GPs are averaged (iterate::run_gibbs_ensemble). 1 = single chain, byte-identical. N>1 marginalises chain RNG/phase stochasticity (lcWGS analogue of --phase-ensemble); cost linear in N. usize_or.max(1)." },
    Knob { name: "LCWGS_PBWT_DEPTH", group: "lcwgs", kind: Kind::Value, default_repr: "16", user_facing: true, doc: "PBWT match depth: number of nearest neighbors stored per query at each storage site. envu.unwrap_or(16)." },
    Knob { name: "LCWGS_PBWT_MODULO_CM", group: "lcwgs", kind: Kind::Value, default_repr: "0.002", user_facing: true, doc: "PBWT selection sweep frequency in cM; neighbors stored at each multiple of this distance. envf.unwrap_or(0.002)." },
    Knob { name: "LCWGS_ADAPT_EMIT", group: "lcwgs", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "GL-adaptive emission: soften low-confidence per-hap likelihoods toward flat (0.5/0.5) by w=|h0-h1|^pow before the HMM. Gate: if is_err() return None (unset = no-op, byte-identical). Cached as Optio..." },
    Knob { name: "LCWGS_ADAPT_EMIT_POW", group: "lcwgs", kind: Kind::Value, default_repr: "1.0", user_facing: false, doc: "Exponent for the LCWGS_ADAPT_EMIT confidence weight w=|h0-h1|^pow (>1 softens moderate band more, <1 gentler). .parse().unwrap_or(1.0). Read only when LCWGS_ADAPT_EMIT is set." },
    Knob { name: "LCWGS_ADAPT_MIN_GL", group: "lcwgs", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Coverage-adaptive per-hap GL floor: at high coverage (mean-GL-peakedness >= LCWGS_SPLIT_GL_THR) raise min_gl to LCWGS_ADAPT_MIN_GL_HI to clamp manufactured false-HETs. Gate: is_ok() AND LCWGS_MIN_G..." },
    Knob { name: "LCWGS_ADAPT_MIN_GL_HI", group: "lcwgs", kind: Kind::Value, default_repr: "0.01", user_facing: false, doc: "High-coverage min_gl floor applied when LCWGS_ADAPT_MIN_GL engages. .parse().unwrap_or(1e-2)." },
    Knob { name: "LCWGS_BURNIN_DIPLOID", group: "lcwgs", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Run the Gauss-Seidel sweep + genotype-preserving DMM re-phase during burn-in too, not only main (real-vs-simulated tradeoff). is_ok(); byte-identical when off." },
    Knob { name: "LCWGS_COND_DUMP", group: "lcwgs", kind: Kind::Value, default_repr: "", user_facing: false, doc: "⚠ DUAL-USE single var: as a bare presence flag (is_ok()) at iterate.rs:348 it populates GibbsOutput.cond_final (diagnostic); as a directory path (Ok(dir)) at pipeline.rs:491 it dumps per-chunk cond..." },
    Knob { name: "LCWGS_DMM", group: "lcwgs", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Explicitly force DMM segment phase-commitment (and the Gauss-Seidel main sweep) on; redundant since DMM is already default-ON via LCWGS_NO_DMM.is_err(). is_ok() as one disjunct of the dmm OR-chain." },
    Knob { name: "LCWGS_DMM_GL", group: "lcwgs", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "GL-aware DMM emission: weight segment copy-match by per-site read confidence; presence forces DMM (and gs_main) on. R²-neutral, A/B only. is_ok(); feeds dmm (line 326) and gs_main (line 330)." },
    Knob { name: "LCWGS_DMM_M", group: "lcwgs", kind: Kind::Value, default_repr: "12", user_facing: false, doc: "DMM diplotype conditioning-hap count M (GLIMPSE2 HAP_NUMBER analogue). envu filter(m>=2).unwrap_or(12); values <2 ignored." },
    Knob { name: "LCWGS_DMM_RC", group: "lcwgs", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Force rare-carrier-aware DMM phasing-set injection (and the DMM) on. Raw var is opt-in (is_ok(), unset=false), but it also forces dmm on (326) and dmm_rc on (336). Note: the EFFECTIVE rare-carrier ..." },
    Knob { name: "LCWGS_DMM_RC_BUDGET", group: "lcwgs", kind: Kind::Value, default_repr: "6", user_facing: false, doc: "Max local rare carriers injected per sample into the DMM phasing set (on top of IBD copies). envu.unwrap_or(6)." },
    Knob { name: "LCWGS_DMM_SEG_CM", group: "lcwgs", kind: Kind::Value, default_repr: "1.0", user_facing: false, doc: "DMM segment length in cM for phase-commitment. envf filter(c>0.0).unwrap_or(1.0); values <=0 ignored." },
    Knob { name: "LCWGS_DMM_SWITCH", group: "lcwgs", kind: Kind::Value, default_repr: "2.0", user_facing: false, doc: "DMM per-segment pair-switch penalty (log-units). Parsed as f64 then cast to f32: envf.map(|x| x as f32).unwrap_or(2.0)." },
    Knob { name: "LCWGS_EPSILON", group: "lcwgs", kind: Kind::Value, default_repr: "0.000000000001", user_facing: false, doc: "Imputation HMM emission error rate (ee=1-eps match, ed=eps mismatch); GLIMPSE2 err-imp default 1e-12. envf.unwrap_or(1e-12). Internal calibration knob." },
    Knob { name: "LCWGS_LS_FLAT_EXACT", group: "lcwgs", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "GLIMPSE2-exact flat rule: a site is flat iff its GL triple is all-equal. is_ok(); default off." },
    Knob { name: "LCWGS_LS_RICH_COND", group: "lcwgs", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Phasing-HMM conditioning uses the union of both haps' conditioning sets. is_ok(); default off." },
    Knob { name: "LCWGS_KINDEP_RECOMB", group: "lcwgs", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Force K-INDEPENDENT Li-Stephens recomb 0.04*Ne/max(n_ref,Ne) (GLIMPSE2 form). is_ok() → MODE=1; now redundant since K-independent is the unconditional default (use LCWGS_KDEP_RECOMB to force the old K-dependent form). Cached." },
    Knob { name: "LCWGS_GS_MAIN", group: "lcwgs", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Standalone Gauss-Seidel within-sample diploid sweep during main iters (also forced on when DMM is on). Raw var opt-in is_ok(); measured-negative alone. EFFECTIVE gs_main is ON by default because dm..." },
    Knob { name: "LCWGS_INDEL_FLANK", group: "lcwgs", kind: Kind::Value, default_repr: "25", user_facing: false, doc: "Reference flank (bp) around each indel for building local haplotypes. envu(i64 parser).max(1).unwrap_or(25), cast usize; floored at 1. Read inside IndelModel::build." },
    Knob { name: "LCWGS_INDEL_GAP_EXT", group: "lcwgs", kind: Kind::Value, default_repr: "10", user_facing: false, doc: "Pair-HMM indel gap-extension Phred. ⚠ parsed via i64 envu helper then cast f64 (registry kind u32 is logical; underlying parse is i64). unwrap_or(10)." },
    Knob { name: "LCWGS_INDEL_GAP_OPEN", group: "lcwgs", kind: Kind::Value, default_repr: "45", user_facing: false, doc: "Pair-HMM indel gap-open Phred (GATK flat model). ⚠ parsed via i64 envu helper then cast f64. unwrap_or(45)." },
    Knob { name: "LCWGS_INDEL_HP_MIN", group: "lcwgs", kind: Kind::Value, default_repr: "20", user_facing: false, doc: "Floor (Phred) for the homopolymer-adjusted gap-open; only relevant when LCWGS_INDEL_HP_SLOPE>0. ⚠ i64 envu cast f64. unwrap_or(20)." },
    Knob { name: "LCWGS_INDEL_HP_SLOPE", group: "lcwgs", kind: Kind::Value, default_repr: "0", user_facing: false, doc: "Homopolymer-aware gap-open reduction (Phred per extra repeat unit); default 0 = flat GATK model (ships off). ⚠ i64 envu cast f64. unwrap_or(0)." },
    Knob { name: "LCWGS_KDEP_RECOMB", group: "lcwgs", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Force K-DEPENDENT recomb 0.04*Ne/K. is_ok() in else-if → MODE=2; lower precedence than LCWGS_KINDEP_RECOMB. Cached." },
    Knob { name: "LCWGS_RECOMB_DENOM", group: "lcwgs", kind: Kind::Value, default_repr: "band", user_facing: true, doc: "Li-Stephens recombination denominator (hmm.rs recomb_denom_mode/recomb_band_mult). DEFAULT 'band' = keep the tuned /max(n_ref,Ne) rate for common sites + raise ONLY rare-site (is_common==false) transitions to GLIMPSE2's real default /n_ref via per-site recomb_mult in iterate.rs poly-skip FB (lifts ultra-rare R² markedly, raises OVERALL slightly, cannot regress common bins; no-op when n_ref>=Ne). 'max' = prior shipped K-indep 0.04*Ne/max(n_ref,Ne) (opt-out, byte-identical to pre-band output). 'nref' = global 0.04*Ne/n_ref (GLIMPSE2 non-state-list default applied everywhere; riskier on the common bins). raw(). SCOPE: this knob reaches the IMPUTATION forward-backward only. The founder phasing HMM takes its rate from LsParams::nrho (lcwgs/ls_params.rs), which is hardcoded to the max(n_ref, Ne) form and has no mode switch, so setting this to nref changes half the engine. A/B on the Table-6 benchmark measures the phaser half within noise (+0.0003 R2, t=+1.44, n=6)." },
    Knob { name: "LCWGS_MIN_GL", group: "lcwgs", kind: Kind::Value, default_repr: "0.0000000001", user_facing: false, doc: "Per-haplotype genotype-likelihood floor (GLIMPSE2 min_gl); clamps per-hap likelihood into [min_gl,1-min_gl]; 0 disables. envf.unwrap_or(1e-10) at mod.rs:178. ⚠ ALSO a presence-gate at pipeline.rs:2..." },
    Knob { name: "LCWGS_NO_DMM", group: "lcwgs", kind: Kind::Bool, default_repr: "true", user_facing: false, doc: "DMM segment phase-commitment (GLIMPSE2 rephaseHaplotypes analogue, implies gs_main) is default ON; presence reverts to the parallel-Jacobi sweep. is_err() is the default-ON disjunct of dmm." },
    Knob { name: "LCWGS_NO_DMM_RC", group: "lcwgs", kind: Kind::Bool, default_repr: "true", user_facing: false, doc: "Rare-carrier-aware DMM phasing-set injection is default ON when DMM is on; presence opts out. dmm_rc = dmm && (force_dmm_rc || is_err()). No-op when DMM is off." },
    Knob { name: "LCWGS_NO_FAITHFUL_SELECT", group: "lcwgs", kind: Kind::Bool, default_repr: "true", user_facing: false, doc: "Faithful GLIMPSE2 compressed-sparse-PBWT per-individual conditioning selection is default ON; presence reverts to heuristic per-hap PBWT selection. faithful_select = is_err()." },
    Knob { name: "LCWGS_NO_FOUNDER_PHASE", group: "lcwgs", kind: Kind::Bool, default_repr: "true", user_facing: false, doc: "Faithful GLIMPSE2 phasing-HMM re-phase every iteration is default ON; presence reverts to the faster heuristic DMM sweep. founder_phase = is_err()." },
    Knob { name: "LCWGS_NO_POLY_SKIP", group: "lcwgs", kind: Kind::Bool, default_repr: "true", user_facing: false, doc: "Faithful GLIMPSE2 poly/mono skip (run phasing+imputation kernels only over polymorphic sites, direct-impute monomorphic-in-cond) is default ON; presence reverts to dense all-sites kernels. poly_ski..." },
    Knob { name: "LCWGS_NO_RARE_CARRIER", group: "lcwgs", kind: Kind::Bool, default_repr: "true", user_facing: false, doc: "Rare-allele carrier augmentation with sampled-state reinforcement is default ON; presence disables it. rare_carrier = is_err()." },
    Knob { name: "LCWGS_NO_SPLIT", group: "lcwgs", kind: Kind::Bool, default_repr: "true", user_facing: false, doc: "Presence DISABLES the common/rare deep split (two-depth pass: a second Gibbs pass at k_max LCWGS_SPLIT_KMAX whose dose replaces the main pass at panel MAF in LCWGS_SPLIT_BAND). AUTO engages only when kpbwt > 3000 (the adaptive depth on panels >= 45,463 haplotypes, or an explicit LCWGS_KPBWT) AND the likelihoods are soft (mean GL peakedness < LCWGS_SPLIT_GL_THR); so never by default on 1000 Genomes-size panels. On a biobank-size panel (LCWGS_BIG_PANEL) its unset parts are band 0.005,0.10, k_max 3000 and deep depth 2000. LCWGS_SPLIT_MAF forces it. present()." },
    Knob { name: "LCWGS_PHASE_MAIN_EVERY", group: "lcwgs", kind: Kind::Value, default_repr: "1", user_facing: false, doc: "Re-phase cadence in the main phase (1=every iteration=byte-identical); N>1 re-phases only every Nth main iter. envu.filter(n>=1).unwrap_or(1)." },
    Knob { name: "LCWGS_RARE_CARRIER_ALT_ONLY", group: "lcwgs", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Legacy rare-carrier behaviour: always treat ALT as the rare allele instead of the minor allele min(ac, n_ref-ac). present(); default OFF = minor-allele (handles REF-minor sites like GLIMPSE2). Set to reproduce the prior ALT-only path for A/B." },
    Knob { name: "LCWGS_RARE_CARRIER_MAX", group: "lcwgs", kind: Kind::Value, default_repr: "64", user_facing: false, doc: "Max panel minor-allele count for a site to be treated as rare for carrier augmentation. envu.unwrap_or(64)." },
    Knob { name: "LCWGS_SCAFFOLD", group: "lcwgs", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Scaffold mode: run HMM FB only on common sites and interpolate posterior to rare sites (default off = full FB over all sites). is_ok()." },
    Knob { name: "LCWGS_SELECT_REFRESH", group: "lcwgs", kind: Kind::Value, default_repr: "5", user_facing: false, doc: "PBWT conditioning-set refresh interval in iterations. envu.filter(r>=1).unwrap_or(5); values <1 ignored." },
    Knob { name: "LCWGS_SPLIT_BAND", group: "lcwgs", kind: Kind::Value, default_repr: "0.05,0.10", user_facing: false, doc: "Auto-split MAF band 'lo,hi' applied when the soft-GL gate fires. PRESENCE-GATED: unset (or unparsable, or lo >= hi) = 0.05,0.10, or 0.005,0.10 on a biobank-size panel (LCWGS_BIG_PANEL; not with LCWGS_CHRWIDE_PBWT). parse_band; parsed to (f64,f64), requires lo<hi." },
    Knob { name: "LCWGS_SPLIT_GL_THR", group: "lcwgs", kind: Kind::Value, default_repr: "0.84", user_facing: false, doc: "Mean per-(site,sample) max-normalized-GL peakedness threshold; below = soft/low-coverage → engage split / min-GL clamp. .parse().unwrap_or(0.84). Read at BOTH pipeline.rs:204 (adaptive-min-GL gate)..." },
    Knob { name: "LCWGS_SPLIT_KMAX", group: "lcwgs", kind: Kind::Value, default_repr: "5000", user_facing: false, doc: "Deep conditioning k_max of the SPLIT's second pass. PRESENCE-GATED: unset (or unparsable) = 5000, or 3000 for the auto split on a biobank-size panel (LCWGS_BIG_PANEL; not with LCWGS_CHRWIDE_PBWT); the manual band (LCWGS_SPLIT_MAF) keeps 5000. .parse()." },
    Knob { name: "LCWGS_SPLIT_KPBWT", group: "lcwgs", kind: Kind::Value, default_repr: "", user_facing: false, doc: "Conditioning depth (kpbwt) of the SPLIT deep pass (pipeline.rs split_plan, deep_pass_params). Unset, empty or unparsable = the run's depth, or 2000 for the auto split on a biobank-size panel (LCWGS_BIG_PANEL); the manual band (LCWGS_SPLIT_MAF) keeps the run's depth. Equal to the run's kpbwt = a deep pass at the run's depth (the old deep pass exactly only with the old band and k_max too, e.g. LCWGS_BIG_PANEL=order). 0 is refused (no uncapped selection), and so is any other depth with LCWGS_CHRWIDE_PBWT (one selection at the run's depth serves both passes; the big-panel split does not apply there either); both are said and treated as unset. Everything else in the pass is the run's (seed, schedule, cap order, panel side), so depth 2000 under k_max 3000 makes the deep pass the computation of a whole LCWGS_KPBWT=2000 run (derived from the code, and checked record for record on v3 chr22: 5 runs). usize parse." },
    Knob { name: "LCWGS_SPLIT_MAF", group: "lcwgs", kind: Kind::Value, default_repr: "", user_facing: false, doc: "Manual override MAF band 'lo,hi' for the deep-split (requires lo<hi, else no split: an empty value set in the environment too; --config skips empty values); overrides the auto coverage/panel gate; deep k_max LCWGS_SPLIT_KMAX else 5000 and deep depth LCWGS_SPLIT_KPBWT else the run's on every panel (no biobank-size part). if Ok(s) parse_band; parsed to (f64,f64). Unset = auto." },
    Knob { name: "LCWGS_LSX_BURNIN", group: "imputation", kind: Kind::Value, default_repr: "", user_facing: false, doc: "⚠ Research override for LsParams.burnin (--ls-exact path only). parsed ::<i32>() (registry kind u32 logical; negative would parse). No default — unset leaves LsParams default (5)...." },
    Knob { name: "LCWGS_LSX_KPBWT", group: "imputation", kind: Kind::Value, default_repr: "", user_facing: false, doc: "Research override for conditioning size on the --ls-exact path; sets both kpbwt and kinit. parse::<usize>(). No default — unset (or parse-fail) leaves LsParams defaults." },
    Knob { name: "LCWGS_LSX_MAIN", group: "imputation", kind: Kind::Value, default_repr: "", user_facing: false, doc: "⚠ Research override for LsParams.main (Gibbs main-iter count, --ls-exact path only). parsed ::<i32>() (registry kind u32 logical). No default — unset leaves LsParams default (15)." },
    Knob { name: "LCWGS_LSX_RARE_CARRIER", group: "imputation", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Enable rare-carrier injection on the --ls-exact path. is_ok() (caller.rs:224)." },
    Knob { name: "LCWGS_LSX_RC_ALL_ITERS", group: "imputation", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "OPT-OUT of main-only rare-carrier injection on --ls-exact: PRESENCE makes it run every iteration (main_only = is_err(), caller.rs:227). Unset = main-iters only." },
    Knob { name: "LCWGS_LSX_RC_MAX_MAC", group: "imputation", kind: Kind::Value, default_repr: "16", user_facing: false, doc: "Max minor-allele-count for a rare site to get carrier injection (--ls-exact). envu, unwrap_or(16) (caller.rs:228)." },
    Knob { name: "LCWGS_LSX_RC_TOP", group: "imputation", kind: Kind::Value, default_repr: "3", user_facing: false, doc: "Top carriers injected per rare site (--ls-exact). envu, unwrap_or(3) (caller.rs:229)." },
    Knob { name: "LCWGS_LSX_RC_RUN_CAP", group: "imputation", kind: Kind::Value, default_repr: "64", user_facing: false, doc: "Cap on IBD-run carriers injected (--ls-exact). envu, unwrap_or(64) (caller.rs:230)." },
    Knob { name: "LCWGS_LSX_SERIAL", group: "imputation", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Force serial (non-parallel) per-sample processing on the --ls-exact path (also forced when n_samples ≤ 1). is_ok() (caller.rs:293)." },
    Knob { name: "SELPHI_REFINE_THR", group: "imputation", kind: Kind::Value, default_repr: "0.1", user_facing: true, doc: "Per-sample confidence threshold for the WGS refine engine: at an input chip site a sample with confidence ≥ thr keeps its verbatim hard call; below it uses the panel dosage. parse::<f64>(), unwrap_or(0.1) (imputation_pipeline.rs:872)." },
    Knob { name: "SELPHI_NO_NOCALL_REROUTE", group: "imputation", kind: Kind::Bool, default_repr: "false", user_facing: true, doc: "Opt OUT of no-call re-routing. Default (unset): a MISSING target genotype (GT_MISSING sentinel) is given confidence 0 so it is re-routed to the LS-imputed dosage instead of the scaffold value (the phasing used to clamp no-calls to REF — ~70% of missing carriers were emitted hom-REF). Independent of --refine. Set to 1 to restore the old scaffold-value behaviour. Byte-identical when there are no no-calls. is_one() (imputation_pipeline.rs)." },
    Knob { name: "SELPHI_NO_LD", group: "imputation", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Disable LD correction on chip genetic-map positions in the multi-chr orchestrator (raw cM instead of compute_ld_correction_bm). is_ok() (presence with any value, incl. empty, enables). Default-off ..." },
    Knob { name: "SELPHI_REFINE_CONST_C", group: "imputation", kind: Kind::Value, default_repr: "", user_facing: false, doc: "Test/override constant per-site confidence c applied to EVERY chip site for the hybrid-emission refine spine (eps_eff=(1-c)*0.5 + c*p_err). parse::<f64>(); takes effect ONLY when no real per-site c..." },
    Knob { name: "SELPHI_REFINE_GQ_HI", group: "imputation", kind: Kind::Value, default_repr: "30", user_facing: false, doc: "Upper endpoint of the GQ→input-confidence ramp used by --refine (GQ >= HI → confidence 1). parse::<f64>().unwrap_or(REFINE_GQ_HI const=30.0); no range filter (ramp() guards hi<=lo)." },
    Knob { name: "SELPHI_REFINE_GQ_LO", group: "imputation", kind: Kind::Value, default_repr: "10", user_facing: false, doc: "Lower endpoint of the GQ→input-confidence ramp used by --refine (GQ <= LO → confidence 0). parse::<f64>().unwrap_or(REFINE_GQ_LO const=10.0); no range filter." },
    Knob { name: "LCWGS_NO_EMIT_LOO", group: "lcwgs", kind: Kind::Bool, default_repr: "true", user_facing: false, doc: "Leave-one-out forward emission in the lcWGS FB posterior (GLIMPSE2 schedule) is default ON; setting the var DISABLES it. is_err(); cached. An lcWGS HMM knob." },
    Knob { name: "LCWGS_MAX_DEPTH", group: "io", kind: Kind::Value, default_repr: "250", user_facing: true, doc: "Maximum pileup depth per site in native BAM/CRAM pileup. u32 envu.unwrap_or(250)." },
    Knob { name: "LCWGS_MIN_BQ", group: "io", kind: Kind::Value, default_repr: "20", user_facing: true, doc: "Minimum base quality for native BAM/CRAM pileup GL generation. u32 envu.unwrap_or(20), cast u8." },
    Knob { name: "LCWGS_MIN_MAPQ", group: "io", kind: Kind::Value, default_repr: "20", user_facing: true, doc: "Minimum read mapping quality for native BAM/CRAM pileup GL generation. u32 envu.unwrap_or(20), cast u8." },
    Knob { name: "LCWGS_NO_BAQ", group: "io", kind: Kind::Bool, default_repr: "false", user_facing: true, doc: "Native BAM/CRAM pileup: DISABLE Base Alignment Quality (bcftools mpileup -B). DEFAULT off = BAQ ON when --reference is given (extended BAQ + bcftools' partial-realignment heuristic, bit-identical to htslib/bcftools 1.22; verified against samtools calmd -r -E). Without --reference BAQ is silently unavailable. present()." },
    Knob { name: "LCWGS_FULL_BAQ", group: "io", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Native BAM/CRAM pileup: realign EVERY read (bcftools mpileup -D / --full-BAQ) instead of only the reads the partial heuristic selects at indel/soft-clip columns. Measured -0.05 pp non-ref concordance vs partial (chr22 GIAB); kept for A/B. present()." },
    Knob { name: "SELPHI_BAQ_ORACLE_BAM", group: "debug", kind: Kind::Value, default_repr: "", user_facing: false, doc: "TEST ONLY. Path to a BAM carrying `BQ` tags written by `samtools calmd -r -E`, the parity oracle for the BAQ port (`cargo test --release baq_parity_with_samtools_calmd -- --ignored`). Unset = the test skips. raw()." },
    Knob { name: "SELPHI_BAQ_ORACLE_FASTA", group: "debug", kind: Kind::Value, default_repr: "", user_facing: false, doc: "TEST ONLY. Reference FASTA (with .fai) matching SELPHI_BAQ_ORACLE_BAM, for the BAQ parity test. raw()." },
    Knob { name: "LCWGS_SEED", group: "experimental", kind: Kind::Value, default_repr: "15052011", user_facing: false, doc: "RNG seed of the lcWGS Gibbs chain (GLIMPSE2's default 15052011). The chain is deterministic for a fixed seed; re-running under other seeds illustrates the sensitivity of per-sample accuracy to the seed choice. Measured: six capture libraries x three alternative seeds (18 seed-only deltas vs the default seed): non-ref concordance sd 0.066 pp per sample, max 0.157 (pooled sd / sqrt(6) = 0.027 is a heuristic for the six-sample mean, not a measured sd of paired means, and three seeds do not bound the variability). A knob is compared to the default under the SAME seeds, paired (sample, seed), and any interval on those repeated measures is exploratory (six samples, two trios). --seed does NOT reach this engine (it seeds the array phasers and --ls-exact). usize_or(15052011) (lcwgs/mod.rs LcwgsParams::default)." },
    Knob { name: "LCWGS_GL_DUMP", group: "debug", kind: Kind::Value, default_repr: "", user_facing: false, doc: "Native BAM/CRAM pileup diagnostic: append every covered SNP site's genotype likelihoods to this TSV (pos, ref, alt, depth, P(hom-ref), P(het), P(hom-alt)), one line per site per sample, for a site-by-site comparison with the PL a bcftools mpileup|call pipeline produced from the same reads. Observation only; output unchanged. raw() (lcwgs/bam_pileup.rs)." },
    Knob { name: "LCWGS_NATIVE_PL_QUANT", group: "io", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Native BAM/CRAM pileup: represent each site's errmod genotype likelihoods the way `bcftools call` writes PL -- integer phred, min-normalised, capped at 255 (bam2bcf.c) -- instead of the continuous, uncapped phreds the native path otherwise keeps. Tests whether the representation difference explains the gap between the native and bcftools-likelihood arms on HG005 (-0.089 pp non-ref). MEASURED on the six capture libraries, default seed, paired vs the default: non-ref +0.011 pp (bootstrap [-0.020,+0.051], exploratory), 2/6 wins; per sample -0.006 / +0.038 / -0.012 on HG005 / HG002 / HG004 -- no consistent gain under the default pileup (it is not inert in general: combined with the htslib-style overlap path it moved HG005 by +0.086 pp). The HG005 native-vs-bcftools gap (0.089 pp) is comparable in magnitude to that sample's seed-only deltas (+0.070, -0.033, +0.078), which does not establish its cause. A/B knob. is_one() (lcwgs/bam_pileup.rs finalize_gl_errmod)." },
    Knob { name: "LCWGS_BAQ_STREAMING", group: "io", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Native pileup BAQ: reproduce bcftools mpileup's streaming artefact — a realigned read keeps RAW base qualities at pileup columns BEFORE the column that triggered its realignment. Default off = BAQ qualities at every column of a realigned read. A/B only. present()." },
    Knob { name: "LCWGS_OVERLAP_HTSLIB", group: "io", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Native BAM/CRAM pileup: reconcile overlapping mates the way htslib 1.22 does (overlap_push + tweak_overlap_quality, ported statement for statement with its CIGAR iterators; the path under bcftools mpileup and GLIMPSE2). A paired read waits for its mate; over the overlap, agreeing bases put the summed quality (cap 200) on the mate chosen by Wang(X31(qname))&1 and zero on the other, disagreeing bases keep 0.8x on the higher-quality mate (survivor decides a tie), bases opposite the mate's deletion keep 0.8x if theirs is the survivor; THEN BAQ (deferred, as bcftools runs mplp_realn after the pileup) and the min-BQ filter. The default per-site merge (OverlapState) differs from htslib in three measured ways: interleaved overlapping pairs at one site are counted twice (only the LAST fragment is remembered; 69,617 of 381,675 covered sites on HG005 chr22 read a higher depth than bcftools), agreeing sub-threshold bases are dropped before they can be summed (3,045 sites bcftools covers and we do not), and a disagreement reduced to Q19 is kept against the Q20 filter. With the knob on, depth agrees with bcftools at 380,059 of 381,605 sites and argmax disagrees at 19. MEASURED, six capture libraries x four seeds, same-seed paired contrast vs the default: non-ref concordance -0.013 pp (bootstrap interval [-0.035,+0.008], EXPLORATORY: the 24 pairs are repeated measures of six samples from two trios, not independent draws), 9/24 wins, het recall -0.017 -- no improvement, a slight negative lean, so the default stays. Verified against an independent pysam/htslib oracle (12 base/strand/MQ cases, 28 CIGAR fixtures incl. trailing deletions and ref skips, 6 buffering cases: all pass; unit tests overlap_oracle_tests). Known remaining differences from bcftools: BAQ streaming (LCWGS_BAQ_STREAMING), depth-cap subset selection under the deferred scoring, 3,115 depth-1 sites only bcftools covers. Compatibility A/B knob, not an accuracy lever. present() (lcwgs/bam_pileup.rs PassState::on_read)." },
    Knob { name: "LCWGS_KEEP_SUPPLEMENTARY", group: "io", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Native BAM/CRAM pileup: KEEP supplementary alignments (flag 0x800). Default off = drop them, which deviates from BOTH references rather than matching either: bcftools mpileup's --ff default excludes only UNMAP,SECONDARY,QCFAIL,DUP, and GLIMPSE2 excludes only UNMAP|SECONDARY (its supplementary exclusion is commented out, caller_initialise.cpp:196-199). Measured on the six capture libraries (default seed, paired vs the default): keeping supplementary reads gives non-ref -0.024 pp (bootstrap [-0.074,+0.028], exploratory), 3/6 wins, het recall -0.039; combined with PL quantisation -0.040 -- a negative lean, so dropping them stays the default." },
    Knob { name: "LCWGS_BAM_KEEP_INDELS", group: "io", kind: Kind::Bool, default_repr: "false", user_facing: true, doc: "Legacy (LCWGS_BAM_INDELS=keep): with LCWGS_BAM_INDELS unset, presence keeps the --bam path's indel panel sites IN the chain with flat (prior-only) likelihoods instead of the impute-only default. Measured (six capture libraries, 3 seeds): SNP cost +0.005 pp [-0.052,+0.062] (the -0.04 pp once quoted for it did not reproduce), indels tie impute-only (+0.032 pp), +0.5 GiB peak on a 1000 Genomes-size panel; on v3 with LCWGS_KPBWT=2000, 2,150-2,232 CPU-s and 14.5 GiB at 8 threads vs 1,461-1,570 CPU-s and 9.0-9.1 GiB impute-only at 12 (not measured at the default depth). present()." },
    Knob { name: "LCWGS_BAM_INDELS", group: "io", kind: Kind::Value, default_repr: "", user_facing: true, doc: "lcWGS --bam path, the panel's indel sites (no read evidence): unset = `impute` (DEFAULT): imputed only, the SNPs run exactly as without them (SNP rows byte-identical to `drop`: verified on 12 of 12 samples, 1000 Genomes capture rig and v3) and each indel is a passenger the chain never reads (not selection, rare carriers, sampling or phasing): one extra forward-backward per haplotype per main iteration over its axis plus its polymorphic passengers (flat emission there) gives each passenger's copying posterior. Indels vs GLIMPSE2's, non-ref concordance: capture rig (default conditioning, 3 seeds) 94.463 vs 94.102 (+0.361 [+0.010,+0.712], 16/18), v3 with LCWGS_KPBWT=2000 (3 seeds) 96.096 vs 95.882 (+0.214 [+0.093,+0.334], 17 wins / 1 tie), v3 default conditioning (12 sample-seed pairs) 96.428 vs 95.882 (+0.546 [+0.389,+0.703], 12/12). Per pooled MAF bin the point estimates are above GLIMPSE2 except v3 default < 0.5% (-0.162; 5 wins, 3 losses, 4 ties), and the 95% CIs span 0 at capture >= 5% and < 0.5%, v3 0.5-5% (both conditionings) and v3 < 0.5% (LCWGS_KPBWT=2000: +0.124; 5 wins, 6 ties, 7 losses). Cost on the 1000 Genomes capture rig, 16 threads: one sample 33-34 s / 281-283 CPU-s vs 25.7-27.0 s / 210-211 (same peak), six samples 1,051 vs 779 CPU-s and 9.4-9.7 vs 8.6 GiB; on v3 with LCWGS_KPBWT=2000, 12 threads: 514-541 s / 1,461-1,570 CPU-s / 8.96-9.12 GiB (that arm without indels was timed only at 16 threads: 414-424 s / 1,492-1,553 CPU-s / 11.9 GiB; the impute path's chunks build their own panel slice, the prepared cache is skipped); v3 default conditioning, 12 threads: 1,098-1,139 s / 3,051-3,174 CPU-s / 9.35-9.71 GiB (old index-order default without indels 794-816 s / 2,571-2,631 / 11.9 GiB). `drop` = no indel rows (the previous default, byte-identical); `keep` = in the chain (flat, or read-scored with LCWGS_INDEL_REALIGN + --reference). With LCWGS_BAM_INDELS unset, LCWGS_BAM_KEEP_INDELS or LCWGS_INDEL_REALIGN + --reference keep their previous meaning (in the chain), and LCWGS_SCAFFOLD drops them (an explicit `impute` with LCWGS_SCAFFOLD exits 2). With LCWGS_INDEL_REALIGN=1 + --reference an impute-only indel folds its own reads into its genotype. Case-insensitive; `1`/`true`/`yes`/`on`/`y` = impute; empty = unset (a dumped --config round-trips empty as unset); `0`/`false`/`no`/`off`/`n` = not impute, their meaning before impute became the default (in the chain with the legacy knobs above, else dropped); another value is said and treated as unset. raw()." },
    Knob { name: "LCWGS_PASSENGER_EVERY", group: "lcwgs", kind: Kind::Value, default_repr: "1", user_facing: false, doc: "LCWGS_BAM_INDELS=impute: run the passengers' forward-backward on every Nth main iteration only (averaging those); 1 = every main iteration. Cost ~ one extra FB per haplotype per run iteration. usize_opt filter(n>=1)." },
    Knob { name: "LCWGS_COUNT_ORPHANS", group: "io", kind: Kind::Bool, default_repr: "false", user_facing: true, doc: "Native BAM/CRAM pileup: include ANOMALOUS read pairs (paired reads NOT flagged proper-pair, 0x2). DEFAULT off = discard them, matching bcftools/samtools mpileup default (anomalous reads — often soft-clipped near structural breakpoints — carry spurious ALT alleles and manufacture false hets, hurting the ultra-rare bin). present() = keep them (samtools --count-orphans). Single-end reads (no 0x1) are always kept." },
    Knob { name: "LCWGS_NAIVE_GL", group: "io", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Native BAM/CRAM SNP pileup genotype-likelihood model. DEFAULT off = the faithful samtools/bcftools revised-MAQ errmod (correlated-read dependency cap + mapQ/neighbour base-quality caps), matching `bcftools mpileup`. present() = the prior naive independent-product model (over-confident at multi-read sites; kept for A/B). No-op on the indel-realign path (always naive). present()." },
    Knob { name: "LCWGS_QUAL_TRUNC", group: "lcwgs", kind: Kind::Value, default_repr: "", user_facing: false, doc: "How the per-sample conditioning union is capped at LCWGS_KPBWT when it exceeds it (it does in every measured selection call: with the default 0.002-cM storage sites on 16-cM chunks the pre-cap union is 5,708-6,332 of 6,332 1kGP haplotypes, median 6,295; 3,956-4,796 of 4,796 on the capture rig). UNSET or EMPTY (a dumped --config round-trips empty as unset) = by haplotype INDEX on panels below 30,311 haplotypes (the selection then collapses to an almost fixed low-index subset — exactly haplotypes 0..K-1 in several measured chunks; every other order measured ties it on the capture rig or loses a MAF bin beyond seed spread on the Table 2b rig, 3 seeds) and GLIMPSE2 rank order (`g2`) on a biobank-size panel (LCWGS_BIG_PANEL). Set to a value it overrides the panel-size default: `0`/`false`/`no`/`off`/`n` = by haplotype INDEX on every panel. `1`/`true`/`yes`/`on`/`y`/`fwd` = best PBWT rank layer first, forward within a layer. `g2` = GLIMPSE2 `compactSelection` order exactly (rank layers ascending, reverse within a layer, sorted membership; 503-fixture parity vs the C++). `hash` = panel-order-INDEPENDENT: the K union members first in a deterministic panel order keyed by panel sample ID + haplotype number (FNV-1a + SplitMix64, seed LCWGS_CAP_HASH_SEED), never by index; `hybrid` = round(LCWGS_HYBRID_RANK_FRAC x K) in `g2` order, the rest of the union by the `hash` order. Under hash/hybrid the selected set is emitted ascending (a union that fits K = the index order exactly; ascending packs fastest) unless K exceeds LCWGS_KMAX with rare carriers on, when it is emitted in priority order (rank part first, also when the union fits) so the KMAX prefix cap keeps the priority. Case-insensitive; cached in OnceLock. Measured on the Table 2b rig. The measured pre-cap union sizes above explain why truncation order matters." },
    Knob { name: "LCWGS_HYBRID_RANK_FRAC", group: "lcwgs", kind: Kind::Value, default_repr: "0.5", user_facing: false, doc: "LCWGS_QUAL_TRUNC=hybrid only: share of the LCWGS_KPBWT cap filled in GLIMPSE2 rank (`g2`) order before the panel-order-independent hashed fill. f64_opt, clamped to [0,1], NaN/non-number = 0.5. 1 = the g2 set, 0 = the hash set." },
    Knob { name: "LCWGS_CAP_HASH_SEED", group: "lcwgs", kind: Kind::Value, default_repr: "6782174911695080094", user_facing: false, doc: "LCWGS_QUAL_TRUNC=hash|hybrid only: seed of the panel order keyed by sample ID + haplotype number (u64; default 0x5E1F20261026CA9E). Separate from LCWGS_SEED so the subset lottery can be measured apart from the chain's." },
    Knob { name: "SELPHI_PBWT_WALK_CAP", group: "imputation", kind: Kind::Value, default_repr: "auto", user_facing: false, doc: "Per-side cap on matches recorded per site by the imputation PBWT scan (longest first). Unset = auto: 200 on panels >= 100,000 haplotypes (MESA x TOPMed 9,047 -> 4,381 s, no MAF bin lower), off below (byte-identical). Explicit value wins; 0 disables." },
    Knob { name: "SELPHI_PBWT_SPARSE_SCAN", group: "imputation", kind: Kind::Value, default_repr: "1", user_facing: false, doc: "Shared PBWT forward: a target carrying a site's MAJORITY allele visits only the minority-allele positions of its match block (per-site index of minority positions + 64-position divergence maxima, built once per site per group) instead of walking the whole block. Same positions, same order, same running divergence -> byte-identical output (unit test sparse_scan_is_byte_identical_to_the_walk). `0` = the full walk, for A/B. raw()!=\"0\"; cached in OnceLock." },
    Knob { name: "SELPHI_EVAL_CONST_DS_NAN", group: "debug", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "--evaluate: select the alternative per-site R² rule, under which a site whose imputed dosage is constant while the truth varies is DROPPED from its MAF bin (NaN) instead of scoring r² = 0. That rule gives each tool a different site set and favours a tool that emits a flat dosage at hard sites. Default off (r² = 0). present(); cached in OnceLock." },
    Knob { name: "LCWGS_SEL_DIAG", group: "debug", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Print, per faithful-selection call, the PRE-CAP distinct union size of the PBWT rank layers, how many samples the LCWGS_KPBWT cap actually bit, and the retained maximum haplotype index — the numbers that decide whether the cap ORDER (LCWGS_QUAL_TRUNC) can matter. present(); cached in OnceLock." },
    Knob { name: "LCWGS_CHUNK_DIAG", group: "debug", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Print per-chunk diagnostic summary (cM range, n_var, gl3 sum, panel ones, mean dose). is_ok()." },
    Knob { name: "LCWGS_MEMTRACE", group: "debug", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Print gated RSS checkpoints (from /proc/self/statm) at labeled pipeline stages to locate the memory peak. is_ok(); re-read on every memtrace() call (not cached)." },
    Knob { name: "LCWGS_RAW_GL", group: "debug", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Bypass the HMM: emit raw per-sample expected dose from input GL (g1+2*g2) with flat (1/3) GP. Diagnostic only. is_ok()." },
    Knob { name: "LCWGS_TIMING", group: "debug", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Emit per-phase wall-time / HMM micro-profiling Instant timers for the Gibbs loop (zero overhead when unset; cached in OnceLock). is_ok(). Read at TWO sites: iterate.rs:347 (GibbsConfig.timing) and ..." },
    Knob { name: "LCWGS_TRACE_POS", group: "debug", kind: Kind::Value, default_repr: "", user_facing: false, doc: "Comma-separated genomic positions to white-box trace (AF/dose/carrier-fraction). split(',').parse to Vec<i64>; requires cond_final populated (set LCWGS_COND_DUMP too). Unset = no trace." },
    Knob { name: "LCWGS_TRACE_SAMPLE", group: "debug", kind: Kind::Value, default_repr: "0", user_facing: false, doc: "Sample index to trace for LCWGS_TRACE_POS. parse, unwrap_or(0)." },
    Knob { name: "SELPHI_DEBUG", group: "debug", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Master debug-logging toggle (distinct from _ITER/_SAMPLE). Enabled when set to \"1\" (log.rs:44)." },
    Knob { name: "SELPHI_DIPLOID_NOCALL_K", group: "experimental", kind: Kind::Value, default_repr: "50", user_facing: false, doc: "Number of nearest backward-PBWT neighbours whose majority allele fills a no-call the phasing left missing (expands outward, skipping missing neighbours). Swept on v3 chr22: K=50 optimal (+0.0024 SNP), K=20 too noisy (+0.0007), K=100 dilutes (+0.0011); K=100/200/400 lowered SNP R2 0.8875 -> 0.8862. usize_or(50) (diploid/mod.rs fill_missing_local_vote)." },
    Knob { name: "SELPHI_DIPLOID_INTRA_N", group: "imputation", kind: Kind::Value, default_repr: "2", user_facing: true, doc: "Diploid intra-run phase ensemble: number of phase members averaged from ONE phasing chain (the Viterbi solve + N-1 thinned post-burn-in Main MCMC samples, which the chain computes and otherwise discards). Averaging the imputation over them marginalizes phase uncertainty at ~1x phasing cost (vs N independent phasings) but N imputation passes; default-on (N=2: +~0.005 SNP / +~0.007 indel R2 on real arrays, +25-30% wall, already above the Beagle-phased ceiling). Set 1 to opt out (single Viterbi solve, byte-identical to the single-member output). Auto-forced to 1 under --sample-batch-size and --phase-only. Overridden by --phase-ensemble N when N>1. usize_or(2) (imputation::ensemble::resolve_members)." },
    Knob { name: "SELPHI_HMM_DEDUP_OLD", group: "debug", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Restore allele-only imputation HMM deduplication and its previous grouped arithmetic for A/B comparisons. Default groups require identical chip alleles, match membership and incoming priors; group mass is corrected in initialization, forward/backward combination, pruning, CSR sparsification and cross-window priors to preserve the uncompressed model. Changes output where duplicate candidates exist. is_one() once per calculate_weights call (imputation/hmm.rs)." },
    Knob { name: "SELPHI_HMM_RENORM", group: "imputation", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Renormalize each Li-Stephens CSR weight row to sum 1 AFTER the 1/(n_states+1) sparsity threshold. Default (unset) = the shipped behaviour: the row is normalized, then sub-threshold entries are zeroed WITHOUT renormalizing, so each row's surviving sum is 1-(truncated mass) and varies row to row. Consequences: interpolation divides by (1-t)*sum_w(start)+t*sum_w(end), so a row that lost more mass is slightly down-weighted against its neighbour; and summing CSRs across phase-ensemble members is a mass-weighted rather than arithmetic mean of the member dosages. Enabling makes both exact. MEASURED R2-NEUTRAL on chr22 801s (OVERALL 0.4776 unchanged, per-sample 0.915204 -> 0.915205), i.e. the truncated mass is near-uniform in practice; kept opt-in so the default output stays byte-identical. is_one() (imputation/hmm.rs finalize_weights)." },
    Knob { name: "SELPHI_NE_FLOOR", group: "imputation", kind: Kind::Value, default_repr: "100000", user_facing: true, doc: "Floor for the auto-derived imputation Ne: auto_ne = max(round(36.4*n_ref), SELPHI_NE_FLOOR), applied only when --est-ne is unset (<=0). Default 20000 = the shipped floor (byte-identical). The linear 36.4*n_ref rule is calibrated on panels >= ~4,800 haplotypes; below that it under-sets Ne (the optimum plateaus around ~175k rather than scaling linearly down), so raising the floor (e.g. 175000) keeps small panels near their optimum while leaving large panels untouched (their 36.4*n_ref is already >> floor, so the floor never binds). MEASURED on a 1,500-haplotype Emirati chip->WGS panel with SELPHI_NE_FLOOR=175000: prephased (impute-only) OVERALL R2 +0.0007 genome-wide (chr22 alone +0.0023), which flips the head-to-head vs Beagle 5.5 from a tie to a small Selphi win at every panel; the unphased (phase+impute) arm is unchanged (phasing-bound, not Ne-bound). Kept opt-in (default unchanged) so published numbers do not shift; flip the default only after a broader small-panel calibration. i64_or(20000) (imputation_pipeline.rs auto-Ne derivation)." },
    Knob { name: "SELPHI_PRUNE_THRESH", group: "imputation", kind: Kind::Value, default_repr: "0.005", user_facing: false, doc: "Per-haplotype row-mass fraction below which the chip/WGS Li-Stephens HMM zeroes a state at every chip site in both passes when the original candidate haplotype count exceeds 5000; survivors are rescaled to preserve the row sum. Default 0.005 caps survivors at about 200 haplotypes per row. A compressed group uses threshold times its member count. Smaller fractions keep more haplotypes (floored at 1/original_candidate_count); no pruning at counts <=5000. SELPHI_HMM_DEDUP_OLD=1 restores the reduced-state count and group-level threshold. f64_or(0.005), OnceLock-cached (imputation/hmm.rs calculate_weights)." },
    Knob { name: "SELPHI_MP_MIN_COUNT", group: "imputation", kind: Kind::Value, default_repr: "1", user_facing: false, doc: "Match-processing step-8 eviction threshold: a haplotype must appear MORE than this many times across the window's per-variant top-K lists to be kept (a per-variant fallback keeps all top-K when a site would empty). Default 1 = shipped behaviour (evict single-appearance haps); 0 disables the eviction entirely. Accuracy impact is unmeasured. usize_or(1), OnceLock-cached (imputation/match_processing.rs process_matches)." },
    Knob { name: "SELPHI_MP_FREQ_WEIGHT", group: "imputation", kind: Kind::Value, default_repr: "1", user_facing: false, doc: "Set 0 to disable the global-similarity weighting in match scoring: compute_normed_scores multiplies each match length by freq in [0.1,1.0] derived from the hap's WHOLE-WINDOW total match length, penalizing a locally-perfect but globally-dissimilar hap up to 10x; 0 = raw match length (also in the degenerate rmax==rmin branch, where the shipped 0.55 constant cancels out of threshold/ordering anyway). Unset or any other value = shipped weighting. Accuracy impact is unmeasured. raw()!=Some(\"0\"), OnceLock-cached (imputation/match_processing.rs compute_normed_scores)." },
    Knob { name: "SELPHI_NO_P10_FILTER", group: "imputation", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Keep EVERY matched haplotype in the chip/WGS HMM front-end: skip the 10th-percentile match-count eviction in filter_matches_fast but still derive p_err from the same cutoff — isolates the filter's effect from the error rate (the two are otherwise entangled in one function). Accuracy impact is unmeasured. is_one(), OnceLock-cached (imputation/hmm.rs filter_matches_fast)." },
    Knob { name: "SELPHI_PERR_OVERRIDE", group: "imputation", kind: Kind::Value, default_repr: "", user_facing: false, doc: "REPLACE the chip/WGS HMM emission error rate p_err outright (filter_matches_fast normally derives it as cutoff/n_sites, floored by 1e-4 AND by the --p-err CLI value, default 0.025) — bypasses BOTH floors so p_err can be swept down to ~1e-4 and below. Must be in (0,1): the emission ratio divides by it. Accuracy impact is unmeasured. raw().parse::<f64>(), OnceLock-cached (imputation/hmm.rs filter_matches_fast)." },
    Knob { name: "SELPHI_PERR_EM_DIAG", group: "debug", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Print one [PERR-EM] line per target haplotype and imputation window: the window p_err and the mean posterior mass outside each chip site's match set (hmm::unmatched_posterior_mean), the estimate the adaptive emission reads. Observation only (output unchanged). is_one(), OnceLock-cached (imputation/hmm.rs calculate_weights)." },
    Knob { name: "SELPHI_INPUT_FILTER", group: "imputation", kind: Kind::Value, default_repr: "auto", user_facing: true, doc: "What a target record its caller filtered (FILTER set and not PASS) means (--input-filter). auto (default) = its calls are no-calls in the genotype readers (refine confidence 0, auto-route sniff, passthrough written as no-calls, gVCF blocks occupied), its likelihoods read as given by lcWGS; missing = lcWGS flat likelihoods too; keep = everything as given. DeepVariant 30x chr22 (RefCall 0/0 and ./. records), HG001 R2 0.98983 -> 0.99637; DRAGEN HG001 0.99811 -> 0.99871. io::target_io::input_filter_missing() / likelihoods_filter_missing()." },
    Knob { name: "SELPHI_VARIANT_ONLY_FILL", group: "imputation", kind: Kind::Value, default_repr: "1", user_facing: true, doc: "0 = impute the panel sites a variant-only input does not list instead of reading them as reference homozygotes (io::variant_only). Default: one sample with no reference-homozygous call and at least 1,000 ALT calls, at SELPHI_VARIANT_ONLY_DENSITY or more records per Mb, gets them as 0/0 calls along the span of its records, gaps longer than SELPHI_VARIANT_ONLY_MAX_GAP_KB left out. HG002 30x chr22 variant-only: R2 0.9806 -> 0.9969, false ALT calls 1,648 -> 132. --callable BED overrides the regions. raw() != \"0\"." },
    Knob { name: "SELPHI_VARIANT_ONLY_CHRX", group: "imputation", kind: Kind::Value, default_repr: "1", user_facing: false, doc: "0 = never read chromosome X's unlisted panel sites as reference (the other variant-only fill rules unchanged). The chrX sex test leaves the added sites out, and when the fill ran a sample whose own chrX calls are ALT calls alone is one X below 25% heterozygous (pedigree::VARIANT_ONLY_HAPLOID_MAX_HET). (variant_only::chrx_fill)" },
    Knob { name: "SELPHI_FILL_PHASE", group: "phasing", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Keep the sites a variant-only (or gVCF/all-sites) fill read as reference in the phasing scaffold. By default they are left out (homozygous, no phase to decide; phase_rare works at heterozygous sites only), which they otherwise make phase_common run over every panel site of a genome. is_one() (diploid::scaffold::drop_filled)." },
    Knob { name: "SELPHI_FILL_HMM_ANCHORS", group: "imputation", kind: Kind::Value, default_repr: "1", user_facing: false, doc: "0 = leave every SELPHI_FILL_HMM_MAF candidate out of the imputation HMM; default keeps those whose weights the output reads (the anchors of untyped and re-routed sites). raw() != \"0\" (io::pipeline::window_masks)." },
    Knob { name: "SELPHI_FILL_HMM_MAF", group: "imputation", kind: Kind::Value, default_repr: "0", user_facing: false, doc: "Panel minor-allele frequency below which a site a variant-only (or gVCF/all-sites) fill read as reference is left out of the imputation PBWT and HMM, as a no-call is (weights put back by cM blending; still written as 0/0). 0 = every filled site in. f64_opt() (io::variant_only::hmm_skip)." },
    Knob { name: "SELPHI_VARIANT_ONLY_DENSITY", group: "imputation", kind: Kind::Value, default_repr: "300", user_facing: false, doc: "Records per Mb at or above which a variant-only single-sample input counts as a genome (absent panel sites read as reference); below it (an exome, ~50/Mb) only a warning asks for --callable. f64_opt(), >= 0." },
    Knob { name: "SELPHI_VARIANT_ONLY_MIN_DP", group: "imputation", kind: Kind::Value, default_repr: "8", user_facing: false, doc: "Median FORMAT/DP (first sample, first 20,000 records) at or above which a variant-only input's omissions are read as reference (at 4x a caller misses 25% of ALT sites; at 10x the fill still raises R2 0.9738 -> 0.9765). Without DP, SELPHI_VARIANT_ONLY_MIN_GQ decides. f64_opt()." },
    Knob { name: "SELPHI_VARIANT_ONLY_MIN_GQ", group: "imputation", kind: Kind::Value, default_repr: "20", user_facing: false, doc: "Without FORMAT/DP: median GQ at or above which a variant-only input's omissions are read as reference (DRAGEN 30x 46; bcftools 30x / 10x / 4x 99 / 71 / 21). Without DP or GQ the file is taken as a standard-depth genome. f64_opt()." },
    Knob { name: "SELPHI_VARIANT_ONLY_REF_GB", group: "imputation", kind: Kind::Value, default_repr: "4", user_facing: false, doc: "Most GB of panel matrix (typed sites x ceil(n_ref/64) x 8 B) a variant-only fill may create on one chromosome; above it the unlisted sites are imputed (a 75,552-haplotype panel needs 9.4 KB per site). f64_opt(), > 0." },
    Knob { name: "SELPHI_VARIANT_ONLY_MAX_GAP_KB", group: "imputation", kind: Kind::Value, default_repr: "100", user_facing: false, doc: "A stretch longer than this (kb) with no record of a variant-only input is left to imputation, not read as reference (the caller may have had no reads there). f64_opt(), > 0." },
    Knob { name: "SELPHI_ALL_WEIGHT_ROWS", group: "imputation", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Keep the copying weights of every typed-site row of a window. By default the rows nothing reads are left empty (io::pipeline::needed_weight_rows): a typed site written verbatim needs its row only as the anchor of an interval holding an untyped or re-routed site, and as a no-call run's called neighbour for the member fold; the output is identical either way. is_one() (io::pipeline::weight_rows_mask)." },
    Knob { name: "SELPHI_WINDOW_MAX_MARKERS", group: "imputation", kind: Kind::Value, default_repr: "100000", user_facing: true, doc: "Most typed markers one imputation window holds (its overlap with the next: an eighth of it); 0 = cM windows only (--window-cm). A window's weights are kept for every typed marker of every target haplotype until it is interpolated, so a WGS-density input in 80-cM windows (855,000 markers on chromosome 22) peaked at 46-51 GB for one sample. Array windows (10,000-60,000 markers) never reach it. parse::<usize>(), unwrap_or(100000)." },
    Knob { name: "SELPHI_PERR_FIXED", group: "imputation", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Restore the fixed emission floor (--p-err for every haplotype). Default: the adaptive floor (window_process::PerrAdapt): in a target haplotype's first window the HMM runs at the --p-err floor, measures its posterior mass outside the match set, and when that exceeds SELPHI_PERR_ADAPT_LO runs again at a floor rising linearly to SELPHI_PERR_ADAPT_MAX at SELPHI_PERR_ADAPT_HI; later windows keep it. A real array's genotype errors raise that mass (GIAB chr21 x v3 panel: 0.0004 error-free, 0.0010 / 0.0020 / 0.0035 with 0.2 / 0.5 / 1% of genotypes flipped, where the best floor is 0.025 / 0.05 / 0.07 / 0.07). is_one(), OnceLock-cached." },
    Knob { name: "SELPHI_PERR_ADAPT_LO", group: "imputation", kind: Kind::Value, default_repr: "0.0008", user_facing: false, doc: "Adaptive emission: unmatched posterior mass at or below which the floor stays at --p-err. f64_opt(), default 0.0008." },
    Knob { name: "SELPHI_PERR_ADAPT_HI", group: "imputation", kind: Kind::Value, default_repr: "0.002", user_facing: false, doc: "Adaptive emission: unmatched posterior mass at which the floor reaches SELPHI_PERR_ADAPT_MAX. f64_opt(), default 0.002." },
    Knob { name: "SELPHI_PERR_ADAPT_MAX", group: "imputation", kind: Kind::Value, default_repr: "0.07", user_facing: false, doc: "Adaptive emission: the highest floor it sets. f64_opt(), default 0.07." },
    Knob { name: "SELPHI_PRUNE_DIAG", group: "debug", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Print a per-window [PRUNE-DIAG] line: mean surviving (nonzero) states per HMM row after prune_row (forward + backward passes) and mean final CSR nnz per row, aggregated over the window's target haps — tells whether the >5000-state prune binds (mean_surviving << mean_states) before spending a biobank run on SELPHI_PRUNE_THRESH. Off = a cached-bool branch per row, no counting. is_one(), OnceLock-cached (imputation/hmm.rs, printed by prune_diag_report from imputation/window_process.rs process_window_hmm)." },
    Knob { name: "SELPHI_SPLICE_CONST_TAIL", group: "debug", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Restore constant extrapolation from the last owned chip anchor to a window splice for A/B comparisons. Default uses the next overlap anchor when its CSR weight row and endpoint are available; no-overlap and chromosome-end tails stay constant. Shared by batched and unbatched output paths. is_one(), OnceLock-cached in io/pipeline.rs build_intervals." },
    Knob { name: "SELPHI_INTERP_CM", group: "imputation", kind: Kind::Bool, default_repr: "true", user_facing: false, doc: "DEPRECATED, now the default and inverted: cM interpolation of untyped sites is on unless SELPHI_INTERP_RANK=1. Setting this has no effect." },
    Knob { name: "SELPHI_INTERP_RANK", group: "imputation", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Restore rank-linear interpolation of untyped sites: t = the variant's ordinal position between its two flanking typed anchors, instead of its cumulative genetic position (genmap::cumulative_cm_floored, every step at least 1e-7 cM). cM interpolation is the default: measured a UNIFORM WIN on chr22-801 (every MAF bin up, none down) and never-regress on MESA 100 x TOPMed chr20 (every bin >=, per-sample 0.899739 -> 0.899758), RSS unchanged, wall unchanged. The rank-linear t misplaces the crossover exactly where an interval spans a recombination hotspot, which is why every other imputer interpolates in cM. Kept only as an A/B escape hatch. Changes output where rank-linear and cM-linear placement differ. is_one(), read once per run (imputation_pipeline.rs run; orchestrate.rs run_multi_chr)." },
    Knob { name: "SELPHI_DIPLOID_RARE_DISPATCH", group: "experimental", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "DEPRECATED, now the default and inverted: use SELPHI_DIPLOID_SKIP_FIRST_DISPATCH=1 to get the OLD skip-first order back. Position-first dispatch in both diploid segment-HMM forward passes -- INIT (window head) and COLLAPSE (segment head) run unconditionally and the rare-hom skip applies only in the RUN position, matching SHAPEIT5 haplotype_segment_single.cpp:105-117 and Selphi's own backward pass. Position-first dispatch and non-finite checks prevent a shadowed INIT from poisoning the window. An f64 forward with the same skip-first order cannot repair it: threshold-only underflow checks (1e-30 / 1e-300) are false for NaN, allowing an all-zero transition vector to reach all_trans and causing the sampler to commit the last diplotype of every affected segment." },
    Knob { name: "SELPHI_DIPLOID_SKIP_FIRST_DISPATCH", group: "experimental", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Restore the OLD skip-first dispatch order in both diploid segment-HMM forward passes, where the rare-hom skip is tested before the position so a skip on a window or segment head shadows INIT/COLLAPSE. Position-first (SHAPEIT5 haplotype_segment_single.cpp:105-117, and what this file's own backward pass does) is the default since 2026-09-03. Byte-identical on chr22-801 (the rare path is thin there); kept only as an A/B escape hatch." },
    Knob { name: "SELPHI_HMM_NO_XWIN_PRIOR", group: "experimental", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Skip the cross-window forward prior entirely -- neither build nor consume it. Measured INERT on chr1 (801 samples, 5,769,087 variants, 4 real windows, 1KG panel): output is byte-identical with the true posterior, with the old boundary-set indicator, and with no prior at all, because finalize_weights rewrites rows 0-1 and n-2/n-1 of every window and the first overlap/2 markers are discarded. Skipping it frees in_flight_haps x n_states x 16 bytes of held memory plus the time to build it. Not yet the default: verified on ONE panel scale only." },
    Knob { name: "SELPHI_HMM_XWIN_BOUNDARY_PRIOR", group: "experimental", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Restore the OLD cross-window forward prior, which was read AFTER the last block's boundary fill had replaced the final forward row with 1/nh at the matched states and 0 elsewhere -- a match-set indicator that had forgotten the accumulated forward evidence. The default now reads the row before that fill, so each window hands the next one the real posterior. The fill is harmless to the weights (finalize_weights rewrites rows n-2 and n-1 of every window), which is why this went unnoticed. Affects multi-window chromosomes only: chr21 and chr22 are single-window and never build the prior." },
    Knob { name: "SELPHI_HMM_TOTAL_RECOMB_DENOM", group: "experimental", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Imputation HMM: divide the per-site recombination shift by the summed group size over ALL states instead of over the haplotypes MATCHED at that site, which is what makes the kernel mass-preserving (the shift is added over all n_states either way, so the shipped divisor inflates the injected mass by the all-states/matched ratio). NOT the default: the shipped auto-Ne (36.4 * n_ref, floor 100,000) was swept on top of the current kernel, so the inflation is absorbed into that constant and moving one without re-sweeping the other makes the copying model far stickier than anything validated. A one-parameter A/B at fixed Ne is not a verdict." },
    Knob { name: "SELPHI_DIPLOID_DISPATCH_DIAG", group: "debug", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Count diploid forward-pass rare-hom skips that land on a window head or a segment head. NOTE these counters are STRUCTURALLY PINNED TO ZERO and prove nothing: GenotypeGraph::build only breaks a segment at a locus whose own het/sca flag reaches predicted_unfold == 4, so every segment head after the first is HET or SCA and the var_is_hom-gated skip chain can never reach a segment head; the window-head case needs graph variant 0 itself to be panel-rare. A zero reading here is a tautology, not evidence -- to measure skip volume, use SELPHI_DIPLOID_ALPHA_DIAG, which counts skips at a segment's LAST locus (that is the case save_alpha was mislabelling)." },
    Knob { name: "SELPHI_DROP_LONG_ALLELES", group: "experimental", kind: Kind::Bool, default_repr: "false", user_facing: true, doc: "Drop reference-panel variants whose CHROM/REF/ALT exceeds 255 bytes while building an SRP. Set by the --drop-long-alleles CLI flag. By default such variants are KEPT: the SRP variant index writes a longer field as 255 plus a u32 length behind an i64::MIN marker (srp::helpers::push_variant_vbin; panels without long alleles keep the original layout byte for byte). This retains 53,791 long-allele variants in the v3 panel for both BREF3 and BCF input. The skip happens in the reader before genotypes are extracted, so the variant index and the haplotype matrix cannot fall out of step; the number of dropped records is logged. is_one() (srp/bcf_reader.rs process_region, srp/writer.rs BREF3 path)." },
    Knob { name: "SELPHI_PBWT_SHARE", group: "experimental", kind: Kind::Value, default_repr: "0", user_facing: false, doc: "Run the imputation PBWT SORT once per B target haplotypes instead of once per target. 0 (the default) = AUTO, three gates per window: (1) memory -- B from /proc/meminfo MemAvailable, a third of what is free minus a 4 GB reserve divided by (threads x per-in-flight-target cost), capped at 16; (2) candidate fraction -- OFF when mc/n_ref < 0.6, because the shared scan walks the WHOLE panel (about n_ref/mc of the per-target scan: the 1.29x the split diag saw at 0.78; at 0.36, the 75,552-hap reference panel, it alone costs the per-target forward and sharing loses at every B and cohort size); (3) one round -- B <= ceil(batch haps / threads), so the groups still fill the pool exactly once (the RAM-only gate ran 12 target haps as ONE serial 75k-hap sort while 15 threads idled, PBWT 3.0 -> 37.0 s on a consumer-array chromosome; flooring instead of ceiling put 200 haps into 17 groups = a second round on one thread). OFF below 4 because a smaller group is not worth the memory. MemAvailable, not MemTotal, because this decision must not double-book RAM another job on the box is already using; it is recomputed per window since n_var (hence the per-target cost) differs by window and the machine may have got busier. Safe to decide from machine state precisely because the output does not depend on B. 1 = off outright; any other value is used as B verbatim. The sort depends only on the panel -- the same a/d at every site serve every target -- so only the neighbour scan around a_inv[target] has to stay per-target, with its own candidate mask and its own ht/top-K buffers. Byte-identical by construction; it is the SELPHI_FULL_PANEL_PBWT=2 geometry with the sort hoisted out of the target loop. MEASURED CEILING, and it is far below what the raw sort-work ratio suggests: SELPHI_PBWT_SPLIT_DIAG puts the sort at 67.6% of the forward on MESA 100 x TOPMed and 43.2% on chr22 x 1KG, and the scan grows ~1.29x under sharing because it walks past non-candidates, so B -> infinity is ~2.4x on the forward there and ~1.4x here. Costs memory: every target in a group holds its forward match buffers (2 * n_var * fl_fwd * 4 bytes) and its ht (n_ref * 8) live at once, ~15.6 MB per in-flight target on MESA x TOPMed, so the peak grows by about threads * (B-1) * that. usize_or(0), OnceLock-cached (imputation/window_process.rs share_batch)." },
    Knob { name: "SELPHI_PBWT_SPLIT_DIAG", group: "debug", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Split the imputation PBWT forward pass into the half a shared sort would amortise and the half it would not, printing a [SPLIT] line per window. SORT = pbwt_forwards_ad plus the y[i] = row[a[i]] gather, which depends only on the panel; SCAN = the per-target left/right neighbour walks. The window log PBWT=... and [STAGE] split separate PBWT from HMM without separating sort from scan: a 97-99% PBWT share does not imply 97-99% shareable work. Reads 67.6/32.4 on MESA 100 x TOPMed and 43.2/56.8 on chr22 x 1KG. Also counts scan steps (positions walked), which is how you see that the walk covers ~35-40% of the panel per site. Times two Instant::now() pairs per site per target -- about 1 s in a 650 s pass, with byte-identical output. is_one(), OnceLock-cached (imputation/pbwt.rs split_diag; reported from imputation/window_process.rs)." },
    Knob { name: "SELPHI_FULL_PANEL_PBWT", group: "experimental", kind: Kind::Value, default_repr: "0", user_facing: false, doc: "Force the full-panel PBWT regime in the per-target imputation loop instead of taking it only when n_cand < FULL_PANEL_HMM_THRESHOLD. 1 = full-panel sort AND full-panel scan, i.e. no per-target candidate set at all -- the naive shared PBWT. 2 = full-panel sort with the neighbour scan restricted to this target's candidate set, which makes the SORT target-independent (hence shareable) while the recorded matches stay exactly the per-target ones. These modes measure full-panel sort and scan behavior independently of shared-sort scheduling. MEASURED: mode 1 is a clean superset at the MATCH level (superset diag: zero anomalies, zero length differences, on chr22-801 x 1KG at three candidate ratios and on MESA 100 x TOPMed) but LOSES at the dosage level -- MESA 100 x TOPMed OVERALL R2 0.692026 -> 0.691105, down in all six measurable MAF bins -- because the top-mc candidate ranking also keeps globally-irrelevant haplotypes out of the per-site top-K. Mode 2 is byte-identical to the default (chr22 at mc=1000 and mc=3500, MESA at the auto mc). NEITHER MODE IS FASTER: both still run one sort per target, and mode 2 sorts n_ref+n_haps instead of mc, so it is ~1.3x slower. They measure accuracy and byte-identity, not speed. usize_or(0), OnceLock-cached (imputation/window_process.rs full_panel_mode)." },
    Knob { name: "SELPHI_PBWT_SUPERSET_DIAG", group: "debug", kind: Kind::Value, default_repr: "0", user_facing: false, doc: "For the first N target haplotypes of every imputation window, run BOTH the candidate-subset and the full-panel PBWT and compare their CSC match sets site by site, printing a [SUPERSET] line per window. Observation only -- the imputed output still comes from the regime the run would have used, so a diag run is byte-identical to a plain one. Counters: kept (in both), displaced (a subset match the full run dropped in favour of an at-least-as-long match in a saturated column -- the ranking working as intended), ANOMALY (dropped for any other reason -- the number that would refute the shareability argument), added (matches only the full panel found), and length disagreements. Reads zero anomalies and zero length differences everywhere measured so far, which is the empirical form of 'the divergence between a target and a reference haplotype does not depend on which other haplotypes are in the panel'. Costs one extra full-panel PBWT per diag'd target. usize_or(0), OnceLock-cached (imputation/window_process.rs superset_diag_ntgt)." },
    Knob { name: "SELPHI_HMM_THREADS", group: "imputation", kind: Kind::Value, default_repr: "0", user_facing: true, doc: "Threads for the per-target PBWT+HMM map only; 0 (default) uses the global --threads pool. The run's memory peak IS that map: each in-flight target holds scratch sized n_window_sites * n_states, so peak = a fixed part + (threads x per-target working set). MEASURED on MESA 100 x TOPMed chr20 with --threads 16 throughout: 0 (=16) -> 43.26 GB / 6:45; 8 -> 30.76 GB / 11:00; 4 -> 23.59 GB / 20:31, fitting 14.8 GB + 1.78 GB x threads to within 6%. Byte-identical at every value. CAVEAT, measured: narrowing the reduction to the HMM stage is only marginally better than lowering --threads outright -- global --threads 4 is 21.94 GB / 21:22 against this knob's 23.59 GB / 20:31 -- because on this rig the per-target map is nearly the whole runtime. Use it as a precise memory dial, not as free speed. Note also that at biobank cohort sizes the COHORT slope (~0.0219 GB/sample) dominates: capping HMM threads does not make an unbatched 5,000-sample run fit. usize_or(0), OnceLock-cached (imputation/window_process.rs hmm_pool)." },
    Knob { name: "SELPHI_ENSEMBLE_MAX_SAMPLES", group: "imputation", kind: Kind::Value, default_repr: "0", user_facing: true, doc: "Cohort size above which the intra-run phase ensemble drops to one member. 0 (the default) = no cap. The ensemble runs the per-target imputation HMM once per member and averages the copying weights; it costs N x the HMM stage and nothing else, so its price is the HMM's share of the wall, which grows with the cohort until the HMM IS the wall: +25-30% on chr22 x 801 samples, +72% on chr21+22 x 801, ~+90% on MESA 5,000 x TOPMed (window 1: 11,949 s HMM vs 999 s interpolation+output). The accuracy it buys does not scale the same way (+0.005 R2 on a 6-sample array, +0.0023 on 801 samples). It defaults to NO CAP on purpose: the only evidence on what the ensemble is worth at 5,000 samples points the other way (unbatched N=2 scored OVERALL 0.6209 against 0.6148 for a batched N=1 run -- a confounded comparison, but the clean same-binary control has not been run). Set it when wall time matters more than the last ~0.005 R2. The --sample-batch-size option forces 1 because streaming output cannot retain multiple weight sets. Unbatched biobank runs pay 2x unless capped; the run logs that cost. An explicit SELPHI_DIPLOID_INTRA_N or --phase-ensemble overrides this cap. usize_or(1000) (imputation/ensemble.rs resolve_members)." },
    Knob { name: "SELPHI_NO_MI_COLLECT", group: "experimental", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Skip the forced mimalloc collect (rayon::broadcast(mi_collect(true))) that runs on every worker thread at each imputation window boundary. mimalloc purges a freed page lazily, on the NEXT allocator call of the thread that owns it; the window loop frees a window's weight CSRs on the main thread while the workers that allocated them idle, so nothing purged and RSS never came down between windows. MEASURED on MESA 200 x TOPMed chr20: MIMALLOC_PURGE_DELAY=0 took the peak 11.34 -> 8.88 GB (win2-start RSS 9,956 -> 4,146 MB) at +8% wall; the per-window collect is the surgical form of the same thing. The diploid phasing MCMC collects the same way after every iteration (each sample's buffers are freed on the worker that ran it): chr1, 54 WGS trio children, --phase-only, 3 runs each, peak 11.61-11.88 -> 11.01-11.31 GiB, wall unchanged. Allocator policy cannot change output. Set 1 to restore the no-collect behaviour for A/B. is_one(), OnceLock-cached (common/mem.rs)." },
    Knob { name: "SELPHI_HMM_TL_KEEP_MAX", group: "experimental", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Select the alternative thread-local scratch policy in the chip/WGS HMM: keep the forward and weight buffers at the largest size any haplotype ever needed, for the life of the rayon worker. Those buffers are n_window_sites * n_states, and n_states is per-TARGET (MESA 100 x TOPMed chr20: mean 2,276, max ~18,500), so a worker kept the largest hap it ever saw resident for the rest of the run. The default now drops a retained buffer more than 2x larger than the current hap needs and allocates a right-sized one instead. MEASURED worth 0.82 GB of a 42.98 GB peak (42.16 vs 42.98, byte-identical output, wall unchanged) -- real and free, but small: the peak is the LIVE working set of one hap per thread (43.3 GB at 16 threads vs 21.9 GB at 4 on the same rig), not retention. Set 1 only to A/B the memory or to chase an allocator regression." },
    Knob { name: "SELPHI_DIPLOID_ALPHA_DIAG", group: "debug", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Measure the difference between two save_alpha locus labels. Both labels are stored per segment -- the locus that last UPDATED the state (shipped) and the segment's LAST locus (pre-fix) -- and this counts how often they differ, the gap in loci and in cM, and, at the segment boundary where compute_trans_hap consumes it, the ratio between the recombination term yt each label produces. Unlike SELPHI_DIPLOID_DISPATCH_DIAG these counters are NOT structurally pinned to zero: they fire on a rare-hom skip anywhere inside a segment, not only on its head. The rare path needs panel-MAF < 0.001 sites in the phasing set, so a chip x small-panel run reads zero and a chip x TOPMed (n_haps_total ~171k, MAF < 0.001 = AC < 171) run does not. Aggregated over samples x iterations x windows and over both precision twins; reset + printed per phasing run. is_one(), OnceLock-cached (diploid/alpha_diag.rs; reported from diploid/phase_common.rs)." },
    Knob { name: "SELPHI_DIPLOID_ALPHA_SEG_END", group: "experimental", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Use the segment-end Alpha locus label: compute_trans_hap bridges from the segment's LAST locus instead of the last locus that actually updated the state. Under a rare-hom skip at a segment boundary the old label makes the bridge too short, yt too small and the phase too sticky; SHAPEIT5 and this file's own backward pass both use the updated locus. This is the exact A/B for the fix -- paired runs differ only where the rare path fires, and are byte-identical wherever it does not. Pair it with SELPHI_DIPLOID_ALPHA_DIAG to check the rig exercises the path at all before reading a delta. is_one(), OnceLock-cached (diploid/alpha_diag.rs; consumed by both segment-HMM twins)." },
    Knob { name: "SELPHI_SWEEP_NO_MIS_VOTE", group: "experimental", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Opt OUT of voting an allele for no-call genotypes in the diploid PBWT initialisation sweep. Default (unset) = a no-call is marked ambiguous, stops voting REF for its PBWT neighbours, and gets each of its two haplotypes voted from the neighbours (SHAPEIT5 conditioning_set_solve.cpp:112-121 and :149-157). With this option enabled only HETEROZYGOTES are ambiguous, so a no-call enters the sweep, the post-sweep graph rebuild and the whole MCMC as hom-REF (the rebuild reads the bitmatrix, whose bits a MIS variant never sets, so the graph's MIS flag is also lost: measured 2313 missing -> n_missing=0). Set 1 to enable that behavior. Byte-identical on input with no missing genotypes. is_one() (diploid/phase_common.rs run_phase_common_bm)." },
    Knob { name: "SELPHI_PHASE_FM", group: "phasing", kind: Kind::Value, default_repr: "", user_facing: false, doc: "Few-target neighbour sweep of phase_common (diploid::pbwt_fm): with few target haplotypes on a large panel the panel is PBWT-sorted once per phase_common call and every iteration only places the targets in it (LF map + walk back to a stored order), instead of re-sorting the whole panel at every site of every iteration. Writes exactly the cells of the full sweep, so the output is identical either way. Default (unset): on when a cost model says the index is >= 4x cheaper per sweep and the index fits SELPHI_PHASE_FM_MB (one user on the 75,552-haplotype panel: ~1.1 GB on chr2 with orders every 32 sites). 0 = always the full sweep, 1 = index whenever it applies (no cost or memory gate), verify = index AND full sweep, panicking if any cell differs. raw()." },
    Knob { name: "SELPHI_EXTRACT_ORDER", group: "io", kind: Kind::Value, default_repr: "tail", user_facing: false, doc: "Order in which the chip-site bitmatrix extraction reads a tiled SRP: tail (default) = from the end of the file to its head, so a panel just downloaded into a container too small to cache it is read from the page cache where the download left it, and the head (where the interpolation starts) is the part read last; head = from the head, as before. The bitmatrix is identical either way. raw()." },
    Knob { name: "SELPHI_PANEL_CACHE", group: "io", kind: Kind::Value, default_repr: "auto", user_facing: false, doc: "Whether a chip run treats its tiled panel as too big for the page cache (srp::retain::plan): auto (default) = when the tiles exceed the room the process has (MemAvailable, or the room under the cgroup memory limit when less) minus 3.5 x the chip-site bitmatrix (what phasing builds before the interpolation reads the panel again); limited = always; plenty = never. On a limited run windows prefetch during the HMM (SELPHI_PANEL_PREFETCH_MB); with SELPHI_PANEL_DROP_CACHE=1 the bitmatrix extraction also drops the pages it will not keep (or holds in RAM: SELPHI_PANEL_RETAIN_MB) from the page cache and the interpolation the pages behind its reads. Output identical either way. raw()." },
    Knob { name: "SELPHI_PANEL_RETAIN_MB", group: "io", kind: Kind::Value, default_repr: "0", user_facing: false, doc: "Compressed panel tiles (MB) the chip-site bitmatrix extraction leaves held in RAM for the interpolation, which copies them instead of reading the file again (srp::retain; released as the interpolation moves past them). Default none (measured zero-sum with the page cache under one memory limit); auto = on a cache-limited run (SELPHI_PANEL_CACHE) a third of the room above 1 GB. Output identical at any value. raw()." },
    Knob { name: "SELPHI_PANEL_PREFETCH_MB", group: "io", kind: Kind::Value, default_repr: "", user_facing: false, doc: "On a cache-limited run (SELPHI_PANEL_CACHE): bytes (MB) the held panel spans may reach once a window's prefetch, run during the window's HMM from its first stripe on, has filled them (srp::retain::window_io); 0 = no prefetch (the window preloads its first ~500 MB as before). Default: what is held plus three quarters of the room left after the window's expected growth (earlier windows' measured working set + 1 GB for the interpolation's buffers; the first window: the run's peak minus current RSS after phasing, none without phasing) and 512 MB. A monitor thread keeps 512 MB of room by releasing spans, and each interpolation group reserves its own allocations (decode bounded from the tile headers) the same way. Not under --sample-batch-size. Output identical at any value. usize_opt()." },
    Knob { name: "SELPHI_PANEL_DROP_CACHE", group: "io", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "On a cache-limited run (SELPHI_PANEL_CACHE), 1 = drop from the page cache (posix_fadvise DONTNEED) the panel pages the run holds in RAM or has read for the last time, so the cache keeps the stripes still to be read. They are the file's pages for every process: set it only where the panel is the run's own (a container task that downloaded it). Output identical either way. is_one()." },
    Knob { name: "SELPHI_PHASE_FM_MB", group: "phasing", kind: Kind::Value, default_repr: "", user_facing: false, doc: "Memory budget (MB) of the few-target neighbour sweep index (SELPHI_PHASE_FM). Default: three quarters of what is available above 512 MB at the first sweep (MemAvailable, or the room under the cgroup memory limit when smaller; 2 GB if unknown). Densest fitting layout first: panel orders kept every 32 sites (64..512 otherwise: slower locates), each chunk's haplotype-major alleles kept with the index if they fit too (else transposed again every sweep, the largest chunk's as scratch); the full sweep runs when nothing fits. Output identical at any value. usize_opt()." },
    Knob { name: "SELPHI_PHASE_WINDOW_BUDGET_MB", group: "phasing", kind: Kind::Value, default_repr: "", user_facing: false, doc: "Extra memory (MB) a batch of phasing windows run in parallel may hold, split across the samples phased at once (diploid::phase_common::window_par_budget). Default: a sixteenth of MemAvailable at the first call, within 16-512 MB. The output is identical at any value; only how many windows run at once changes. usize_opt()." },
    Knob { name: "SELPHI_PHASE_ONLY_RARE_REF_GB", group: "experimental", kind: Kind::Value, default_repr: "4.0", user_facing: false, doc: "Memory budget (GB) for building the FULL-chip reference bitmatrix on the `--phase-only` diploid path. phase_common only needs the common-MAF subset, so that path used to skip the full matrix entirely — which left `phase_rare` with no reference panel at all, silently falling back to target haplotypes only and producing a worse rare-variant phase than the same input gets in an integrated impute run. It is now built whenever `n_chip * ceil(n_ref/64) * 8` bytes fits this budget (a chr22 array x 1KG is 5.6 MB; a WGS target x TOPMed would be ~21 GB). Default 4 GB (was 2) so a whole WGS chromosome 1 against a 4,478-haplotype panel (3.2 GB) gets it: the private-het routing it enables (SELPHI_DIPLOID_PRIVATE_RARE) takes 54 trio children's chr1 switch error from 1.88% to 1.69%, lower for all 54 over three seeds; the union scaffold it also enables (SELPHI_DIPLOID_SCAFFOLD_SOURCE) puts 3.0 M sites in the common stage instead of 1.8 M, which is the extra time (see README). On a target without no-calls it lives only until the phasing scaffold is chosen: phase_rare reads the panel at the scaffold sites from the phase_common matrix and keeps its own rare sites' rows (54 MB on whole-chr1 WGS, 54 trio children x 4,478 haplotypes), so the budget bounds a transient held before the MCMC, not the run's peak; with no-calls the no-call fill needs every row and it is kept. Set 0 to always skip. f64_or(4.0) (imputation_pipeline.rs run_phasing)." },
    Knob { name: "SELPHI_PED_LOCK", group: "experimental", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Lock the hets that `--ped` resolved from a trio/duo: they enter the genotype graph as VAR_SCA (pre-phased), so the diploid segment HMM carries one orientation per segment instead of re-sampling each het, which is SHAPEIT5's scaffold semantics. Without `phased_flags`, `var_set_sca` is unreachable and the MCMC re-samples pedigree phase while retaining the imputed GENOTYPES. Locking the phase measures negative and is therefore opt-in: 54 trios x 9,283 array sites, 75,757 hets locked and verified 99.95% correct against WGS truth, cost -0.0037 site R2 / -0.0021 per-sample (paired t=-5.71) and raised switch error 1.08% -> 1.41%. The phase is right; the graph is not — locking 82% of hets lets segments run to the MAX_AMB=22 ceiling (91,629 -> 69,107 segments) and the HMM cannot switch copied haplotype inside a segment. is_one() (diploid/mod.rs diploid_phase_bm_prefiltered)." },
    Knob { name: "SELPHI_DIPLOID_SCAFFOLD_MAF", group: "experimental", kind: Kind::Value, default_repr: "0.001", user_facing: false, doc: "Minor-allele-frequency threshold selecting the diploid phasing scaffold (the common-variant subset the genotype graph, the conditioning PBWT and the segment HMM run on). The frequency is computed over THIS RUN's target cohort, so the scaffold shrinks with the batch: at AN=2 (one sample) only heterozygous sites clear 0.001, leaving 1802 of 9283 chr22 GSA chip sites, while an 801-sample batch keeps any site with 2+ minor alleles. Set 0 to scaffold on every called site regardless of batch size. Default 0.001 = shipped, byte-identical. When nothing clears it (a one-sample run with no heterozygous call, e.g. a male chrX) the scaffold is every called site, as with 0. f32_or(0.001) (diploid::scaffold::select, used by the single- and multi-chr paths; NOT diploid/mod.rs, where --phase-panel has no reference and cohort frequency is the right notion). Accuracy impact is unmeasured." },
    Knob { name: "SELPHI_IBD2_PANEL_SORT", group: "debug", kind: Kind::Bool, default_repr: "0", user_facing: false, doc: "A/B only: find the diploid phasing's IBD2 tracks with the genotype PBWT even when the run has <= 64 targets (the default there compares each target with the others bit-parallel). Both give identical tracks for every pair that involves a target, the only ones the sweep reads (unit test on random cohorts). is_one() (diploid/phase_common.rs)." },
    Knob { name: "SELPHI_PAR_COLLAPSED_CONF", group: "phasing", kind: Kind::Value, default_repr: "0.1", user_facing: false, doc: "Input confidence given to the typed PAR calls of a male whose PAR genotypes all arrived homozygous (prephase::collapsed_par_calls: homozygous non-PAR chrX and no heterozygote among >= 50 called PAR sites, the signature of an array reporting male chrX as single letters, ~half of which are heterozygous in truth). Default 0.1 (at the re-route threshold: the typed call is written as given, the HMM emission there is nearly flat). Measured, PAR1 imputed SNP R2 on three such men: off 0.602/0.640/0.653 -> 0.1: 0.683/0.691/0.717 (0.05 about the same but re-routes the typed calls); 0 loses the call entirely and is worse. 1 = off. f64_opt() (prephase::par_collapsed_conf)." },
    Knob { name: "SELPHI_MAP_EDGE_OLD", group: "debug", kind: Kind::Bool, default_repr: "0", user_facing: false, doc: "A/B only: imputation clamps positions outside the genetic map to its end value (typed sites beyond it share one cM). Default: every engine extrapolates at the chromosome's mean rate. Only the edge model: the other map rules (falling cM held flat, chrX PAR maps joined, genome-wide maps filtered by contig) stay. is_one() (genmap::edge_model)." },
    Knob { name: "SELPHI_MAP_EDGE_END", group: "debug", kind: Kind::Bool, default_repr: "0", user_facing: false, doc: "A/B only: extrapolate beyond the genetic map at the rate over its last (first) 5 cM, as Beagle 5 does, in phasing and imputation. Measured worse for phasing (54 trios, five seeds: +0.007 pp switch error, 5 of 5 seeds). is_one() (genmap::edge_model)." },
    Knob { name: "SELPHI_DR2_DIPLOID", group: "debug", kind: Kind::Bool, default_repr: "0", user_facing: false, doc: "A/B only: write DR2 with the diploid-dosage estimator (variance of the diploid dosage across samples over 2p(1-p), which is 0 at every site of a one-sample run). Default: the per-haplotype estimator of Browning & Browning 2009 (Var(p) / (p-bar(1 - p-bar)) over haplotype ALT probabilities), defined for one sample. is_one() (io::dosage_stats)." },
    Knob { name: "SELPHI_INPUT_PHASE_GATE", group: "imputation", kind: Kind::Value, default_repr: "0.05", user_facing: true, doc: "Phased input (default, no --keep-input-phase / --trust-input-phase / --force-phasing): the input is re-phased and a sample keeps its given phase as ensemble member 0 (with the re-phasing chain's Viterbi solve as member 1) when at most this fraction of its consecutive heterozygous pairs at the chip sites disagree in relative phase with the chain's; above it the sample gets the chain's members alone, as under --force-phasing. A sample with fewer than 50 such pairs keeps its phase. 801-sample chr22 rig: Beagle/SHAPEIT5 phase 4.0% (p95 6.3%), Beagle + 2% switches 5.9%, random 50%. f64_or() (imputation::input_phase)." },
    Knob { name: "SELPHI_DIPLOID_REPLICAS", group: "phasing", kind: Kind::Value, default_repr: "3", user_facing: true, doc: "Phasing replicas. Every target sample is phased as K copies in one run (same genotypes, each copy its own MCMC random stream), banned from conditioning on each other (they are IBD2 over the whole chromosome; the ban is also set explicitly), and the imputation averages over ALL copies' ensemble members (K x SELPHI_DIPLOID_INTRA_N) through the ordinary member fold. Output keeps one column per original sample: typed-site haplotypes are copy 0's first member, dosages come from the averaged weights. UNSET = automatic: K=3 when the phasing engine runs on <= SELPHI_DIPLOID_REPLICAS_MAX_SAMPLES (8) target samples and no given phase enters the ensemble (an unphased input, or a phased one under --force-phasing); off for a phased input under the input-phase default or --trust-input-phase (its members stay {given, chain} or the chain's) and under --keep-input-phase (no phasing); off, quietly, under --phase-only, --sample-batch-size and SELPHI_ENSEMBLE_CHAINS. K >= 2 forces K copies (an explicit request is refused with a note under those three flags; on a phased input under the input-phase default the given phase is offered as member 0 ahead of the copies' members); 1 or 0 = off, the pre-replica output. Why: the default members come from one chain, and chains with different seeds share most switch errors because the PBWT initialisation sweep uses no randomness (one user vs the 75,552-haplotype panel: 73-75% of switch errors shared between two seeds, 57-58% between co-phased copies). Six consumer arrays, one user per run, chr1-22 + X, 4 threads: autosomal SNP R2 .96262 -> .96436 (+0.0017), indel .79611 -> .79989 (+0.0038), per-sample +0.0021, 6/6 users up on SNP and indel; chrX SNP +0.0002 / indel +0.0012 (men identical); CPU +28%, peak memory +2-3%. A copy alone phases worse than the default chain, which is why --phase-only does not use it. usize_opt (diploid::replicas)." },
    Knob { name: "SELPHI_DIPLOID_REPLICAS_COHORT_MAX", group: "phasing", kind: Kind::Value, default_repr: "1000", user_facing: false, doc: "Largest unphased cohort (above SELPHI_DIPLOID_REPLICAS_MAX_SAMPLES) that gets the automatic two-copy, one-member-each phasing replicas: the ensemble keeps two members but the second comes from an independent copy. 801 1000 Genomes array targets chr22 0.4869 -> 0.4899 (two seeds), chr1 0.5755 -> 0.5782, every MAF bin up; MESA 100 x TOPMed +0.0023/+0.0056; CPU +7..+21%, peak within 0.2 GB. Larger cohorts are not yet measured and stay off. usize_or() (diploid::replicas::cohort_max)." },
    Knob { name: "SELPHI_DIPLOID_REPLICAS_MAX_SAMPLES", group: "phasing", kind: Kind::Value, default_repr: "8", user_facing: true, doc: "Largest target cohort the automatic phasing replicas (SELPHI_DIPLOID_REPLICAS unset) apply to: they cost K x the phasing and K x the imputation HMM (+28% CPU for one user, 3 copies), which a single-user production run pays and a cohort should not. An explicit SELPHI_DIPLOID_REPLICAS ignores it. usize_or(8) (diploid::replicas::max_samples)." },
    Knob { name: "SELPHI_ENSEMBLE_CHAINS", group: "experimental", kind: Kind::Value, default_repr: "", user_facing: false, doc: "Experimental: build the diploid phase ensemble from K >= 2 INDEPENDENT phasing chains (seeds seed..seed+K-1, phased in parallel) instead of thinned Main samples of one chain (single-chr path). Unset = the intra-run default. Accuracy impact is unmeasured. usize_opt() (imputation::ensemble::independent_chains)." },
    Knob { name: "SELPHI_DIPLOID_NOCALL_OBSERVED", group: "debug", kind: Kind::Bool, default_repr: "0", user_facing: false, doc: "A/B only: input no-calls enter the diploid genotype graphs rebuilt after the PBWT init sweep as the sweep's voted genotype (observed by the segment HMM, never imputed) and the output keeps the post-phasing k-NN vote at them. Default (unset): they stay missing and the segment HMM imputes them as SHAPEIT5 does (IMPUTE in the backward, a draw per MCMC iteration, the Main-iteration average in the final solve; common-variant no-calls keep that imputed allele in the output). 2% no-calls, 3 seeds: 801-sample chr22 chip cohort x 1KG overall R2 +0.0038..+0.0044 (every MAF bin), per-sample +0.0008; --phase-panel 801 x 22:30-32 Mb switch error 1.878% -> 1.841%, no-call genotype concordance 0.9903 -> 0.9971; 54 trio children 2.5625% -> 2.5214%. Single-sample runs are unaffected (their no-calls are dropped before phasing). is_one() (diploid/phase_common.rs nocall_observed)." },
    Knob { name: "SELPHI_ANC_POST", group: "phasing", kind: Kind::Value, default_repr: "apply", user_facing: true, doc: "Ancestry-aware long-range phase correction of the diploid solve (diploid/anc_phase.rs): apply (default) | report (decide and log per sample, change nothing) | off (byte-identical to before 2026-10-24). Labelled panel haplotypes = the panel's 1000 Genomes samples (embedded table; AMR, ASW, ACB unlabelled), groups AFR/EAS/EUR/SAS balanced by a seeded choice; 60-site windows, K=5 nearest mismatch means, Viterbi over (group A, group B, orientation) with a PQ flip prior; applied only to a two-continent reading (pair >= 70% of windows, LR >= 0.4/window, <= 0.04 group changes/window). At array density it reads the chip-site panel matrix (imputation; --phase-only within SELPHI_PHASE_ONLY_RARE_REF_GB); at sequencing density (>= SELPHI_AUTOROUTE_WGS_DENSITY sites/Mb) it reads the panel from the SRP at one common SNP per 5 kb and at the junctions, and places each change among all heterozygotes. raw() (anc_phase::mode)." },
    Knob { name: "SELPHI_ANC_PAIR_FRAC", group: "experimental", kind: Kind::Value, default_repr: "0.7", user_facing: false, doc: "SELPHI_ANC_POST gate: least share of windows the path's most frequent pair of different groups must hold. f64_or() (anc_phase::pair_frac_min)." },
    Knob { name: "SELPHI_ANC_LR_MIN", group: "experimental", kind: Kind::Value, default_repr: "0.4", user_facing: false, doc: "SELPHI_ANC_POST gate: least likelihood ratio per window of the two-group path over the best one-group path. f64_or() (anc_phase::lr_min)." },
    Knob { name: "SELPHI_ANC_CHANGE_RATE_MAX", group: "experimental", kind: Kind::Value, default_repr: "0.04", user_facing: false, doc: "SELPHI_ANC_POST gate: most group changes of the two haplotypes per window along the Viterbi path (an F1 holds its groups; an old admixture trades them). f64_or() (anc_phase::change_rate_max)." },
    Knob { name: "SELPHI_ANC_TIMING", group: "debug", kind: Kind::Bool, default_repr: "0", user_facing: false, doc: "Log the ancestry phase check's cost: template choice and transposition (array), marker choice (sequencing density), decisions. is_one() (anc_phase)." },
    Knob { name: "SELPHI_ANC_TEMPLATES", group: "experimental", kind: Kind::Value, default_repr: "", user_facing: false, doc: "SELPHI_ANC_POST parity knob: a file of panel sample IDs used as the labelled templates instead of the seeded balanced choice. raw() (anc_phase::Panel::prepare)." },
    Knob { name: "SELPHI_DIPLOID_PQ", group: "experimental", kind: Kind::Bool, default_repr: "0", user_facing: false, doc: "Write FORMAT/PQ in the --phase-only VCF: at each heterozygote the diploid segment HMM phased, round(-10 log10 P(wrong)) (Integer, capped at 60), P(wrong) the posterior probability, from the stored Main-iteration segment posteriors, that its phase relative to the previous such heterozygote of the sample (cis or trans) is wrong. Within a segment P(cis) = sum_d m_s(d)[relation of d], m_s the mean of the column marginal of the block into s and the row marginal of the block out of s; across a boundary the stored joint block P(d_{s-1}, d_s). The first het of a sample, hets placed by phase_rare and passthrough records carry none (the header line is added only when on); the imputed output carries none. Measured against Mendelian truth (54 1000G trio children, 3 seeds, pairs of consecutive resolvable hets): one child per run on chip sites vs v3 chr22 minus the families, AUC 0.956, Brier 0.0216 vs 0.0289 for a constant rate (skill +0.25), 88% of switches in the lowest-PQ tenth of pairs; the 54 children jointly at WGS density on chr22:20-30 Mb, AUC 0.949, skill +0.32. Calibrated below PQ 7 (PQ 0-2: 66% predicted, 66% observed on chip), over-confident above it (PQ 13-19: 2.8% predicted, 8-9% observed; PQ 20-29: 0.4% vs 2-3%); PQ 60 holds 69% (chip) / 84% (WGS) of pairs at 0.08% / 0.14% observed. Off: byte-identical. is_one(), OnceLock-cached (diploid/sampling.rs pq_enabled)." },
    Knob { name: "SELPHI_DIPLOID_PAIRWISE_OVERRIDE", group: "experimental", kind: Kind::Value, default_repr: "0.5", user_facing: false, doc: "With SELPHI_DIPLOID_SOLVE=pairwise: the posterior probability that a Viterbi consecutive-het relation is wrong above which the pairwise solve reverses it (clamped to [0.5, 1]; 0.5 = the posterior majority of every relation). 0.6 reverses ~0.1% (chip) / 0.05% (WGS) of relations: switch error vs Viterbi, 3 seeds, chip singles -0.025 pp (-55 switches, 3/3 seeds lower), WGS -0.002 pp (-37; +1, -8, -30); six consumer arrays chr20+22, 2 seeds, SNP R2 -0.00025 [-0.0012, +0.0007] (8/24 higher), indel +0.00003. f64_or, OnceLock-cached with the solve mode (diploid/sampling.rs solve_mode)." },
    Knob { name: "SELPHI_DIPLOID_SOLVE", group: "experimental", kind: Kind::Value, default_repr: "viterbi", user_facing: false, doc: "How the diploid final solve decides the output phase: viterbi (default, SHAPEIT5: the joint maximum-probability segment path) or pairwise (each consecutive-heterozygote relation by its posterior majority P(cis) vs 1/2, the decoder that minimises the expected switch count; ties keep the Viterbi relation; each segment then takes the diplotype carrying the decoded alleles so its missing loci follow it; SELPHI_DIPLOID_PAIRWISE_OVERRIDE raises the bar for reversing a Viterbi relation). Measured against Mendelian truth on 54 1000G trio children, 3 seeds: one child per run on chip sites vs v3 chr22, 3.511% -> 3.459% (-116 switches, lower in all 3 seeds); the 54 jointly at WGS density on chr22:20-30 Mb, 2.146% -> 2.151% (+93, higher in all 3): consecutive-het pairs improve on both, but where an unresolvable het lies between two scored hets the composite relation of two near-tied majorities is worse than the joint path's. Six consumer arrays (prod shape, chr20+22, 2 seeds, Table-5 evaluator): SNP R2 -0.0003 [-0.0014, +0.0008] (10/24 higher), indel -0.0001; Viterbi stays the default. Reading the pairs from the coherent mixture of the sampler's forward and backward chains instead of the stored blocks was worse (chip -0.021 pp, WGS +0.003 pp). OnceLock-cached (diploid/sampling.rs solve_mode)." },
    Knob { name: "SELPHI_DIPLOID_IMPUTE_MODE", group: "experimental", kind: Kind::Value, default_repr: "sample", user_facing: false, doc: "Experimental: how each diploid MCMC iteration sets a missing allele from the segment HMM's P(ALT): sample (default, SHAPEIT5: draw it), map (its more probable value; measured equal to sample: cohort per-sample R2 within t 0.9 over 3 seeds), off (keep the sweep's vote: better on 54 trio children, worse than not imputing at all on the 801-sample --phase-panel rig). OnceLock-cached (diploid/sampling.rs)." },
    Knob { name: "SELPHI_DIPLOID_MIS_REPLAY_CAP", group: "debug", kind: Kind::Value, default_repr: "", user_facing: false, doc: "Debug: missing loci whose forward states one per-segment replay of the diploid segment HMM keeps (the backward's SHAPEIT5 IMPUTE). Default (unset): as many states as fit in 8 MiB, at least 16; a segment with more than 2.5x that many missing loci splits the budget into replay slots and in-segment checkpoints (8 + 8 below 16). Set: that many slots and, on longer segments, as many checkpoints. Output never changes, only speed and memory. usize_or() (diploid/hmm_segment.rs replay_split)." },
    Knob { name: "SELPHI_NOCALL_PBWT_FILL", group: "debug", kind: Kind::Bool, default_repr: "0", user_facing: false, doc: "A/B only: let the imputation PBWT read the allele the phasing filled in at a target's no-call chip site. Default: at a site where the target's input confidence is 0 (a no-call, or a --refine call with no confidence) the target takes the majority allele of the panel haplotypes sharing its longest current match, so the no-call ends none of its matches. is_one() (imputation/window_process.rs, pbwt::follow_match_allele)." },
    Knob { name: "SELPHI_UNPHASED_INPUT_ORDER", group: "debug", kind: Kind::Bool, default_repr: "0", user_facing: false, doc: "A/B only: keep an unphased heterozygote's alleles in the order the input lists them (1/0 as 1/0). Default (unset): stored in allele-index order (0/1), so the result does not depend on how a file lists unphased alleles (files made from phased data by swapping | for / keep the true phase in that order: the paper's 54-trio input and the MESA-100 target). is_one(), OnceLock-cached (io/target_io.rs)." },
    Knob { name: "SELPHI_NOCALL_BLEND_ALIGN_OFF", group: "debug", kind: Kind::Bool, default_repr: "0", user_facing: false, doc: "A/B only: in the phase-ensemble fold, take a skipped no-call row of an extra member from one haplotype by that row's own orientation. Default (unset): when the member's orientation against member 0 changes between the called rows either side, the row is rebuilt as the blend of the two called rows each in its own orientation (ensemble::mixed_rows), only where the row is such a blend. is_one() (imputation/ensemble.rs)." },
    Knob { name: "SELPHI_NOCALL_DEDUP_OFF", group: "debug", kind: Kind::Bool, default_repr: "0", user_facing: false, doc: "A/B only: a target that skips its no-call sites (a cohort/batch target with per-sample no-calls) runs its imputation HMM without the state dedup. Default (unset): its dedup groups reference haplotypes by the window's exact allele classes (hap_dedup::allele_classes), which are exact over the sites it calls. is_one(), OnceLock-cached (imputation/window_process.rs)." },
    Knob { name: "SELPHI_NOCALL_FOLLOW", group: "debug", kind: Kind::Bool, default_repr: "0", user_facing: false, doc: "A/B only: select the alternative handling of a target's no-call at a chip site other samples call (a cohort/batch): the PBWT follows the target's longest match through it and the HMM runs over it with a flat emission. Default (unset): the target's PBWT and HMM run over the sites IT calls and its weights are put back on every window row by cM-linear blending (window_process.rs called_sites / expand_weights), i.e. what a single-sample run does by dropping the site; one user per run on six users' merged chr14 site list: per-sample R2 .9473/.9279 -> .9489/.9338 (= dropped .9489/.9324). is_one(), OnceLock-cached (imputation/window_process.rs)." },
    Knob { name: "SELPHI_KEEP_UNCALLED_SITES", group: "debug", kind: Kind::Bool, default_repr: "0", user_facing: false, doc: "A/B only: keep a shared marker whose genotype is a no-call in EVERY sample as a chip site. Default: such a site is imputed as an untyped panel site, which makes a single user's no-call byte-identical to an absent record (it cost 0.011 per-sample R2 at 300 no-calls on chr22). Imputation runs only; --phase-only keeps every site. is_one() (io::target_io::drop_uncalled_sites)." },
    Knob { name: "SELPHI_IBD2_SENTINEL_L", group: "debug", kind: Kind::Bool, default_repr: "0", user_facing: false, doc: "A/B only: seed the IBD2 genotype-PBWT divergence of each bucket's first individual with the site l, as SHAPEIT5's scanIBD2 does, instead of l+1 (Durbin's algorithm 2). The l seed lets a run claim one site too many on its left, so the genotype PBWT and the bit-parallel target scan disagreed by a site at a track's start. is_one() (diploid/ibd2_tracks.rs, phase_rare.rs)." },
    Knob { name: "SELPHI_IBD2_BAN_PANEL", group: "debug", kind: Kind::Bool, default_repr: "0", user_facing: false, doc: "A/B only: scan IBD2 between each target and the reference panel too, and ban an IBD2 panel relative from the target's conditioning set. Default: IBD2 is scanned and banned between targets only, as SHAPEIT5 phase_common does; a reference relative is a phased template, and banning it left a target whose own phased copy was in the panel at 10.50% switch error instead of 0. The old behaviour in full also needs SELPHI_IBD2_SENTINEL_L=1 (the divergence seed). is_one() (diploid/phase_common.rs)." },
    Knob { name: "SELPHI_DIPLOID_SCAFFOLD_SOURCE", group: "phasing", kind: Kind::Value, default_repr: "union", user_facing: false, doc: "Which allele frequency selects the diploid phasing scaffold (threshold SELPHI_DIPLOID_SCAFFOLD_MAF). Default 'union' = every site whose frequency in THIS RUN's target cohort clears it plus every site whose reference-panel frequency does (popcount of the chip-site panel bitmatrix row / n_ref); 'cohort' = the first set only, 'panel' = the second only. Over the cohort the threshold is batch-relative: at one sample only the heterozygous calls clear it (1802 of 9283 chr22 GSA sites), which starved a single user's conditioning PBWT of its homozygous calls. Measured one user at a time, union vs cohort: +0.0078 per-sample R2 (20 1KG samples, chr22, 16/20); neutral on 801 chip samples (chr22, chr1), MESA 100 x TOPMed (3 seeds, +0.00006) and 54-trio switch error (3 seeds, 2.532% vs 2.529%). 'panel' alone lost on MESA in every seed (-0.0014): it drops hets rare in the panel. On the phase-only path the panel set needs the chip-site bitmatrix (built under SELPHI_PHASE_ONLY_RARE_REF_GB); without it only the cohort set is used. diploid::scaffold::Source::from_env (single- and multi-chr paths)." },
    Knob { name: "SELPHI_DIPLOID_PRIVATE_RARE", group: "phasing", kind: Kind::Value, default_repr: "auto (on at WGS density)", user_facing: false, doc: "Private-het routing: drop from the diploid phasing scaffold every chip site whose panel-absent allele (ALT when no reference haplotype carries it, REF when every one carries ALT) has at most one called copy in the run's cohort, so phase_rare places it by its divergence vote (minor allele on the haplotype with the shorter match) instead of the segment HMM, which has no template for it. Hets with a panel carrier stay in the HMM; a record sharing its position with another chip site (split multi-allelic) is never routed; nothing is added to the scaffold. Needs the chip-site panel bitmatrix (always built when imputing and on the multi-chromosome path; on --phase-only under SELPHI_PHASE_ONLY_RARE_REF_GB), otherwise off with a log line; --phase-panel has no reference and ignores it. 1 = on, 0 = off (the previous behaviour, byte-identical); unset = on only when the chip sites are at WGS density (>= SELPHI_AUTOROUTE_WGS_DENSITY sites/Mb), so array runs are unchanged. Measured (one binary, unset vs 1, seeds default/1/2): 54 1000G trio children phased jointly on WGS, chr22:20-30 Mb, 2,239-sample panel without the families: 4,085 sites routed (148 more kept for a shared position), switch error 2.146% -> 1.978% (per child -0.163 pp [-0.211, -0.115], 45/54 lower), flips of panel-absent hets 42.9% -> 32.7%, flips at panel MAC 1-4 925 -> 947 of 16,089 (+0.41 per child [-0.79, +1.60], not significant). Chip gates g1/g2 byte-identical with it on (no chip site routed on 1KG chr22). Whole chromosomes, 3 seeds: trio chr22 2.532 -> 2.356% (54/54 lower), chr1 1.880 -> 1.693% (54/54); MESA 100 x TOPMed array (2 sites routed when forced on): seed-level noise, hence off on arrays. raw() (diploid::scaffold::PrivateRare::enabled_for, single- and multi-chr paths)." },
    Knob { name: "SELPHI_PHASE_NE", group: "experimental", kind: Kind::Value, default_repr: "", user_facing: false, doc: "Pin the DIPLOID PHASING effective population size and switch the burn-in EM re-estimation off. Unset (default) = the shipped path: Ne seeds at DEFAULT_NE=15000 and phase_common re-estimates it during burn-in from graph.n_transitions, an edge count rather than a switch count, which saturates the 1e6 clamp on real data (observed: every run logs 'Ne 15000 -> 1000000' at iteration 1). The segment-HMM transition is 1-exp(-0.04*Ne/n_haps*dist), so a pinned 1e6 makes the per-cM switch rate scale as 1/n_haps: ~27 at 1500 haplotypes, ~8 at 4802 (1KG), ~0.2 at 171054 (TOPMed). The high-Ne behaviour was validated only at the large-panel end (removing it regressed MESA 5K x TOPMed R2 0.6148 -> 0.6120), leaving small panels untested. Accuracy impact is unmeasured. f64_opt() (diploid/phase_common.rs phase_ne_override)." },
    Knob { name: "SELPHI_PHASE_NE_PER_HAP", group: "experimental", kind: Kind::Value, default_repr: "", user_facing: false, doc: "Set the diploid phasing Ne to k * n_haps_total, which holds the segment-HMM switch rate at 0.04*k per cM independently of panel size — the same panel-invariant shape the imputation Ne already has (36.4*n_ref keeps Ne/n_ref constant), instead of the 1/n_haps scaling the shipped path produces. Also disables the burn-in EM re-estimation. Reference points for k: the shipped path is equivalent to k = 1e6/n_haps, i.e. k~667 at 1500 haplotypes and k~5.85 at 171054. Ignored when SELPHI_PHASE_NE is set. Accuracy impact is unmeasured. f64_opt() (diploid/phase_common.rs phase_ne_override)." },
    Knob { name: "SELPHI_PHASE_NE_CAP_WGS", group: "experimental", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Apply the per-haplotype phasing Ne ceiling (SELPHI_PHASE_NE_CAP_PER_HAP) to WGS-density targets as well, i.e. make the scaled ceiling unconditional. A/B knob only: measured on the 54 1KG trio children x 2,239-sample panel, chr22, it is 0.012-0.026 pp WORSE in mean per-trio switch error than the flat 1e6 (same seed, two seeds). Array targets (< SELPHI_AUTOROUTE_WGS_DENSITY scaffold sites/Mb) are unaffected by this knob; they always take the scaled ceiling. is_one() (diploid/phase_common.rs phase_ne_ceiling)." },
    Knob { name: "SELPHI_PHASE_PBWT_DEPTH", group: "experimental", kind: Kind::Value, default_repr: "", user_facing: false, doc: "Pin the diploid phasing's PBWT conditioning depth (neighbours per target haplotype per selection point). Unset: 16 on a reference panel of >= 20,000 haplotypes with <= 50 target samples, 8 with more, the cohort rule round(9 - log10 N) clamped 2..8 below 20,000 haplotypes (diploid/phase_common.rs conditioning_depth). usize_opt()." },
    Knob { name: "SELPHI_PHASE_DEPTH_OLD", group: "debug", kind: Kind::Bool, default_repr: "0", user_facing: false, doc: "A/B only: use the cohort depth rule round(9 - log10 N) for every panel (depth 4 for one target on the 75,552-haplotype v3 panel). is_one() (diploid/phase_common.rs conditioning_depth)." },
    Knob { name: "SELPHI_PHASE_NE_CAP_PER_HAP", group: "experimental", kind: Kind::Value, default_repr: "77.5", user_facing: false, doc: "ARRAY TARGETS ONLY: below SELPHI_AUTOROUTE_WGS_DENSITY scaffold sites/Mb; WGS-density input keeps the flat 1e6 ceiling because the scaled one cost 0.012-0.026 pp trio switch error on the 54-trio chr22 rig (2.539-2.554% vs 2.527-2.528%, two seeds each). Ceiling on the diploid phasing Ne, expressed per haplotype: the burn-in re-estimate is clamped to min(77.5*n_haps_total, 1e6) instead of a flat 1e6. The re-estimate always overshoots (its switch-rate proxy is a graph edge count), so the ceiling is what really sets Ne; a flat one let the per-cM switch rate 0.04*Ne/n_haps drift with panel size (24.9/cM at 1608 haplotypes vs 0.23/cM at 171254) even though the HMM conditions on ~400 haplotypes at every size. 77.5 holds the rate at 3.1/cM until the 1e6 ceiling binds, i.e. from n_haps_total >= 12903 upward, where behaviour is byte-identical to before. MEASURED (array targets, --force-phasing): chr22 801s OVERALL R2 0.4834 -> 0.4876, per-sample 0.915867 -> 0.916032, worst sample 0.819958 -> 0.825926, all 9 MAF bins up; 54-trio SER on a 1500-haplotype panel 10.61% -> ~9.2% against Beagle 9.91%; TOPMed x MESA unchanged (cap inert). Set 0 to restore the flat 1e6 ceiling. f64_or(77.5) (diploid/phase_common.rs phase_ne_ceiling)." },
    Knob { name: "SELPHI_DIPLOID_NOCALL_REF", group: "experimental", kind: Kind::Bool, default_repr: "false", user_facing: true, doc: "Opt OUT of the default diploid no-call scaffold fill: restore clamping no-call (missing) target genotypes to REF before imputation. Default (unset) = fill each no-call (variant, hap) with a LOCAL copying consensus (majority over the K=SELPHI_DIPLOID_NOCALL_K nearest backward-PBWT neighbours among target phased haps + the full-chip reference panel), so the imputer's PBWT candidate selection isn't REF-biased at no-calls (the diploid previously emitted ~70% of missing carriers hom-REF). Fires only when a target genotype is missing → byte-identical on no-missing input. is_one() (diploid/mod.rs _diploid_run)." },
    Knob { name: "SELPHI_REFINE_TEST_SOFT_FRAC", group: "debug", kind: Kind::Value, default_repr: "", user_facing: false, doc: "TEST-ONLY: force a fraction of chip sites to be treated as soft (refine-eligible) to exercise the refine path. parse::<f64>() in (0,1]; no-op/unset by default (imputation_pipeline.rs:842)." },
    Knob { name: "SELPHI_FORCE_AVX2", group: "debug", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Force the AVX2 kernels on an AVX-512 host: diploid segment HMM and PBWT sweep, lcWGS forward-backward and phasing HMM. Phasing output is identical on every path; lcWGS agrees to f32 reduction order. Exact-match: only '1' enables. Checked after SELPHI_FORCE_SCALAR." },
    Knob { name: "SELPHI_FORCE_SCALAR", group: "debug", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Force the scalar code path, disabling all SIMD (AVX-512/AVX2/NEON), for cross-uarch / SIMD parity. Exact-match: only the literal value '1' enables (.ok().as_deref()==Some('1')). PROCESS-WIDE single..." },
    Knob { name: "SELPHI_QUIET_SIMD", group: "debug", kind: Kind::Bool, default_repr: "false", user_facing: false, doc: "Suppress the startup '[selphi] SIMD: <path>' diagnostic line. x86_64-only (cfg-gated). Exact-match: only '1' suppresses (.ok().as_deref()!=Some('1'))." },
    // (SELPHI_FORCE_SCALAR / SELPHI_FORCE_AVX2 also gate the diploid-segment HMM (hmm_segment::seg_path) —
    //  the SAME global vars, not separate knobs, so they are NOT listed twice.)
    Knob { name: "SELPHI_ALLOW_NONRECOMB", group: "run", kind: Kind::Bool, default_repr: "false", user_facing: true, doc: "Escape hatch: allow imputing a non-recombining contig (chrY / chrMT), where the Li-Stephens model is inapplicable and is refused by default. is_ok() (contig.rs:65)." },
];

/// Value knobs whose UNSET state selects ADAPTIVE behavior (they are read both as a value
/// AND via `is_err()` as a presence-gate): e.g. `LCWGS_KPBWT` unset → auto-scale by panel
/// size (pipeline.rs), `LCWGS_MIN_GL` unset → the coverage-adaptive GL floor can engage.
/// `dump_config` emits these COMMENTED-OUT when the env is unset, so round-tripping a
/// default dump back through `--config` does not pin the value and silently disable the
/// adaptive path.
const PRESENCE_GATED: &[&str] = &["LCWGS_KPBWT", "LCWGS_MIN_GL", "SELPHI_DIPLOID_REPLICAS", "LCWGS_SPLIT_BAND", "LCWGS_SPLIT_KMAX"];

// ─────────────────────────────────────────────────────────────────────────────
// Typed accessors — the SINGLE point of env-var access (purist refactor). Every
// env read in the codebase routes through these, so `std::env::var` lives ONLY in
// this file. Each replicates one read idiom BYTE-IDENTICALLY (no trim, matching the
// historical `envu`/`envf` closures and inline `.ok().and_then(parse).unwrap_or`):
//   present(X)      = std::env::var(X).is_ok()              (opt-in; opt-out = !present)
//   is_one(X)       = value == "1"  (== Some("1") idiom)
//   {usize,u32,i64,f64,f32}_or(X,d) = parse, unwrap_or(d)
//   {usize,f64}_opt(X)              = parse → Option         (for the `match`/special sites)
//   raw(X)          = the raw value if present               (for `special` sites that
//                                                              keep their own parse/filter)
// ─────────────────────────────────────────────────────────────────────────────
#[allow(dead_code)] #[inline] pub fn present(name: &str) -> bool { std::env::var(name).is_ok() }
#[allow(dead_code)] #[inline] pub fn is_one(name: &str) -> bool { std::env::var(name).ok().as_deref() == Some("1") }
#[allow(dead_code)] #[inline] pub fn raw(name: &str) -> Option<String> { std::env::var(name).ok() }
#[allow(dead_code)] #[inline] pub fn usize_or(name: &str, d: usize) -> usize { std::env::var(name).ok().and_then(|s| s.parse().ok()).unwrap_or(d) }
#[allow(dead_code)] #[inline] pub fn usize_opt(name: &str) -> Option<usize> { std::env::var(name).ok().and_then(|s| s.parse().ok()) }
#[allow(dead_code)] #[inline] pub fn u32_or(name: &str, d: u32) -> u32 { std::env::var(name).ok().and_then(|s| s.parse().ok()).unwrap_or(d) }
#[allow(dead_code)] #[inline] pub fn i64_or(name: &str, d: i64) -> i64 { std::env::var(name).ok().and_then(|s| s.parse().ok()).unwrap_or(d) }
#[allow(dead_code)] #[inline] pub fn f64_or(name: &str, d: f64) -> f64 { std::env::var(name).ok().and_then(|s| s.parse().ok()).unwrap_or(d) }
#[allow(dead_code)] #[inline] pub fn f64_opt(name: &str) -> Option<f64> { std::env::var(name).ok().and_then(|s| s.parse().ok()) }
#[allow(dead_code)] #[inline] pub fn f32_or(name: &str, d: f32) -> f32 { std::env::var(name).ok().and_then(|s| s.parse().ok()).unwrap_or(d) }

/// Load a Selphi config file (`--config`). For each `KEY = value` line where KEY is a
/// known knob and the env var is NOT already set, set it so the existing env reads pick
/// it up. Bool knobs: `true`/`1` → set to "1"; `false`/absent → left unset. Returns the
/// number of knobs applied. Unknown keys are warned and skipped.
pub fn apply_config_file(path: &str) -> std::io::Result<usize> {
    let text = std::fs::read_to_string(path)?;
    let mut applied = 0usize;
    for raw in text.lines() {
        let s = raw.trim();
        if s.is_empty() || s.starts_with('#') || s.starts_with('[') { continue; }
        let Some((k, rest)) = s.split_once('=') else { continue };
        let k = k.trim();
        // Value: a QUOTED value may contain '#' (take up to the closing quote, preserving it);
        // otherwise strip a trailing '# comment'. Then trim surrounding whitespace.
        let rest = rest.trim_start();
        let v: &str = match rest.strip_prefix('"').and_then(|r| r.split_once('"')) {
            Some((inner, _)) => inner,
            None => rest.split('#').next().unwrap_or("").trim(),
        };
        let Some(knob) = KNOBS.iter().find(|kn| kn.name == k) else {
            eprintln!("[selphi] config: unknown knob '{k}' (ignored)");
            continue;
        };
        if std::env::var(k).is_ok() { continue; } // explicit env overrides the file
        match knob.kind {
            Kind::Bool => {
                // Accept the common spellings; warn (don't silently disable) on anything else.
                match v.trim().to_ascii_lowercase().as_str() {
                    "true" | "1" | "yes" | "on" | "y" => {
                        // SAFETY: set before the engine runs, single-threaded (main, post-parse).
                        unsafe { std::env::set_var(k, "1"); }
                        applied += 1;
                    }
                    "false" | "0" | "no" | "off" | "n" | "" => {} // leave unset
                    other => eprintln!(
                        "[selphi] config: knob '{k}' has unrecognized bool value '{other}' \
                         (treated as off; use true/false)"),
                }
            }
            Kind::Value => {
                let v = v.trim();
                if !v.is_empty() {
                    unsafe { std::env::set_var(k, v); }
                    applied += 1;
                }
            }
        }
    }
    Ok(applied)
}

/// Render the full effective configuration as documented TOML (grouped). For each knob:
/// a bool shows whether its env var is currently set; a value shows the env value or the
/// built-in default. Reproduces the current run's configuration for `--dump-config`.
pub fn dump_config() -> String {
    let mut out = String::new();
    out.push_str("# Selphi configuration (effective values). Pass with --config.\n");
    out.push_str("# Keys are env-var names; an explicit env var overrides this file.\n");
    out.push_str("# user-facing knobs are marked; the rest are advanced/experimental.\n\n");
    let mut last_group = "";
    for k in KNOBS {
        if k.group != last_group {
            let _ = writeln!(out, "\n[{}]", k.group);
            last_group = k.group;
        }
        let _ = writeln!(out, "# {}{}", if k.user_facing { "" } else { "(advanced) " }, k.doc);
        match k.kind {
            Kind::Bool => {
                let set = std::env::var(k.name).is_ok();
                let _ = writeln!(out, "{} = {}", k.name, set);
            }
            Kind::Value => {
                match std::env::var(k.name) {
                    Ok(v) => {
                        let shown = if v.is_empty() { "\"\"".to_string() } else { v };
                        let _ = writeln!(out, "{} = {}", k.name, shown);
                    }
                    Err(_) if PRESENCE_GATED.contains(&k.name) => {
                        // Presence-gated value knob: being UNSET selects an adaptive default
                        // (e.g. LCWGS_KPBWT unset → auto-scale by panel size). Emit it
                        // COMMENTED so round-tripping a default dump through --config does not
                        // pin the value and silently disable the adaptive behavior.
                        let _ = writeln!(out, "# {} = {}   # unset = adaptive; uncomment to pin",
                            k.name, k.default_repr);
                    }
                    Err(_) => {
                        let shown = if k.default_repr.is_empty() { "\"\"".to_string() } else { k.default_repr.to_string() };
                        let _ = writeln!(out, "{} = {}", k.name, shown);
                    }
                }
            }
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::KNOBS;
    use std::collections::HashSet;

    /// Every env var Selphi actually reads (LCWGS_/SELPHI_ prefix, via
    /// `std::env::var` / `envu` / `envf` / `envs`) MUST be in the KNOBS registry — so
    /// `--dump-config` / `--config` stay complete and the registry can't silently drift
    /// when a new knob is added without registering it. Scans src/ at test time.
    /// A `--dump-config` round trip must not pin a default that depends on the panel
    /// size: the depth and the SPLIT band / k_max are written commented out when unset.
    #[test]
    fn dump_leaves_panel_size_defaults_unset() {
        let dump = super::dump_config();
        for k in ["LCWGS_KPBWT", "LCWGS_SPLIT_BAND", "LCWGS_SPLIT_KMAX"] {
            if std::env::var(k).is_ok() { continue; }
            assert!(dump.lines().any(|l| l.starts_with(&format!("# {k} = "))), "{k} not written commented");
            assert!(!dump.lines().any(|l| l.starts_with(&format!("{k} = "))), "{k} written as an active line");
        }
    }

    #[test]
    fn registry_covers_every_env_knob() {
        let reg: HashSet<&str> = KNOBS.iter().map(|k| k.name).collect();
        let mut found: HashSet<String> = HashSet::new();
        let mut stack = vec![std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src")];
        while let Some(dir) = stack.pop() {
            for ent in std::fs::read_dir(&dir).unwrap().flatten() {
                let p = ent.path();
                if p.is_dir() { stack.push(p); continue; }
                if p.extension().and_then(|e| e.to_str()) != Some("rs") { continue; }
                let txt = std::fs::read_to_string(&p).unwrap();
                for pat in ["env::var(\"", "envu(\"", "envf(\"", "envs(\"",
                            "present(\"", "is_one(\"", "raw(\"",
                            "usize_or(\"", "i64_or(\"", "f64_or(\""] {
                    let mut from = 0usize;
                    while let Some(i) = txt[from..].find(pat) {
                        let start = from + i + pat.len();
                        let name: String = txt[start..].chars()
                            .take_while(|c| *c == '_' || c.is_ascii_uppercase() || c.is_ascii_digit())
                            .collect();
                        if name.starts_with("LCWGS_") || name.starts_with("SELPHI_") {
                            found.insert(name);
                        }
                        from = start;
                    }
                }
            }
        }
        let mut missing: Vec<&String> = found.iter().filter(|n| !reg.contains(n.as_str())).collect();
        missing.sort();
        assert!(missing.is_empty(),
            "env knobs read in src/ but missing from config.rs KNOBS (add them): {missing:?}");
    }

    /// PURIST INVARIANT: `std::env::var(` must appear ONLY in config.rs — every env read
    /// routes through the typed accessors (present/is_one/raw/*_or). Guards against a
    /// scattered direct read creeping back into the engine code.
    #[test]
    fn no_scattered_env_reads() {
        let mut offenders: Vec<String> = Vec::new();
        let mut stack = vec![std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src")];
        while let Some(dir) = stack.pop() {
            for ent in std::fs::read_dir(&dir).unwrap().flatten() {
                let p = ent.path();
                if p.is_dir() { stack.push(p); continue; }
                if p.extension().and_then(|e| e.to_str()) != Some("rs") { continue; }
                if p.file_name().and_then(|n| n.to_str()) == Some("config.rs") { continue; }
                if std::fs::read_to_string(&p).unwrap().contains("std::env::var(") {
                    offenders.push(p.display().to_string());
                }
            }
        }
        assert!(offenders.is_empty(),
            "std::env::var must live ONLY in config.rs (route via the accessors); found in: {offenders:?}");
    }
}
